INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-sknf2', 'sknf2', 'Gênero e saúde: uma articulação necessária', NULL, '["Brandão, Elaine Reis","Alzuguir, Fernanda de Carvalho Vecchi"]', 'EDITORA FIOCRUZ', 'SciELO Books', 'books', 2022, NULL, 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', NULL, 'O livro propõe novos e ampliados debates sobre a articulação entre gênero e saúde. A necessidade de abordagens qualificadas sobre gênero e saúde se impõe como tarefa cada vez mais urgente diante das muitas desigualdades sociais em saúde que se evidenciaram no contexto da pandemia de Covid-19. Em meio a esse desafio, a obra reúne reflexões acumuladas pelas autoras em suas experiências de ensino, pesquisa e extensão sobre a temática de gênero, na área da saúde coletiva. Para abordar o tema, as pesquisadoras citam implicações do gênero na saúde que a pandemia tornou ainda mais explícitas. Uma das principais é a sobrecarga feminina sem precedentes em relação à questão do cuidado, gerando esgotamento físico, mental, abandono de postos de trabalho, desemprego e adoecimento. Dessa forma, o volume se propõe a dialogar com pesquisadores, estudantes, profissionais de saúde, gestores públicos, ativistas de movimentos sociais organizados e com o público em geral interessado no debate sobre gênero e saúde.', '[]', '10.7476/9786557081655', '9786557081358', 'https://books.scielo.org/id/sknf2', NULL, NULL, 'https://books.scielo.org/id/sknf2/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-hbhbr', 'hbhbr', 'SUS: o debate em torno da eficiência', NULL, '["Marinho, Alexandre","Ocké-Reis, Carlos Octávio"]', 'EDITORA FIOCRUZ', 'SciELO Books', 'books', 2022, NULL, 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'O volume debate o uso do termo "eficiência" para avaliar a gestão do Sistema Único de Saúde. A obra busca examinar a eficiência no SUS a partir do fato de que tal argumento é sistematicamente utilizado para defender a mercantilização do próprio sistema. Segundo os autores, que se dedicam aos estudos da disciplina da economia da saúde desde a década de 1990, isso acaba encobrindo um constante ataque à ampliação do acesso à saúde promovido pela reforma sanitária brasileira. Os economistas Alexandre Marinho e Carlos Octávio Ocké-Reis argumentam que a palavra eficiência acaba sendo, dessa forma, vulgarizada e servindo para enfraquecer as políticas públicas de saúde. Segundo eles, não há dúvidas sobre as possibilidades de aperfeiçoamentos na gestão do SUS, especialmente por meio da ampliação do financiamento de seus recursos humanos. No entanto, não basta ser eficiente se os resultados não são atingidos e, principalmente, se as necessidades de saúde da população não são atendidas.', '[]', '10.7476/9786557081662', '9786557081334', 'https://books.scielo.org/id/hbhbr', NULL, NULL, 'https://books.scielo.org/id/hbhbr/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-37my2', '37my2', 'Mozambique’s foreign policy towards South Africa: managing asymmetrical economic diplomacy', NULL, '["Wache, Paulo Mateus"]', 'EDITORA DA UFRGS', 'SciELO Books', 'books', 2022, NULL, 'en', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'This Book discusses the Mozambique’s foreign policy framework in general, and towards South Africa, in particular, searching to understand why it has been characterized by the hostility-friendship dichotomy. The Book argues that asymmetry alone cannot explain the occurrence of the dichotomy as suggested by Womack’s asymmetry theory. In the case of Mozambique’s foreign policy, the dichotomy is caused by combination of factors namely: power asymmetry, ideological differences, leadership perceptions, economic disagreements and economic ties. However, it is highlighted that power asymmetry is the main factor of the dichotomy. This complexity and amalgamations of causes of the dichotomy makes it a permanent and distinctive feature of Mozambique’s foreign policy towards South Africa.Thus, the major contribution of this book is twofold. First, it presents a detailed and comprehensive analysis of Mozambique’s foreign affairs as they have interacted with South Africa. Second,by applying asymmetry theory to Mozambique the study makes a significant theoretical contribution to understanding the agency of the smaller side in bilateral asymmetric relationships.', '[]', '10.7476/9786557250709', '9786557250792', 'https://books.scielo.org/id/37my2', NULL, NULL, 'https://books.scielo.org/id/37my2/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-vpwt2', 'vpwt2', 'Os animais peçonhentos na Saúde Pública', NULL, '["Souza, Claudio Maurício Vieira de","Bochner, Rosany"]', 'EDITORA FIOCRUZ', 'SciELO Books', 'books', 2022, NULL, 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'O livro discute os múltiplos fatores que envolvem os acidentes e problemas de saúde causados por animais peçonhentos, especialmente entre as populações mais vulneráveis. Os dois autores são pesquisadores pertencentes a uma geração formada em um dos tantos momentos especiais da trajetória da saúde pública no Brasil: a implantação do Programa Nacional de Ofidismo, em 1986. Dividido em quatro capítulos, o volume tem caráter introdutório e busca provocar a curiosidade do leitor para algumas das dimensões envolvidas nos acidentes por animais peçonhentos. Dessa forma, a obra se distancia das abordagens que se concentram apenas nos aspectos biológicos e médicos dessas questões, mostrando como o modelo de atenção aos acidentes por animais peçonhentos vem funcionando como um ecossistema de políticas públicas do Sistema Único de Saúde (SUS).', '[]', '10.7476/9786557081624', '9786557081280', 'https://books.scielo.org/id/vpwt2', NULL, NULL, 'https://books.scielo.org/id/vpwt2/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-pr3pz', 'pr3pz', 'Consumo alimentar e obesidade: teorias e evidências', NULL, '["Sichieri, Rosely","Pereira, Rosangela Alves"]', 'EDITORA FIOCRUZ', 'SciELO Books', 'books', 2022, NULL, 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'O livro discute aspectos que ajudam a entender por que comemos o que comemos e a produção biológica e social da obesidade, além de analisar políticas públicas de alimentação e nutrição. As autoras apresentam, em três capítulos, uma combinação de análises de condicionantes fisiológicos e biológicos sobre o que comemos, assim como o inegável papel da propaganda na forma como consumimos. A obra reúne ainda contribuições e debates sobre recomendações alimentares, conflitos de interesse entre a ciência e a indústria de alimentos, políticas públicas que possam propiciar condições mais favoráveis para escolhas alimentares, além do advocacy (defesa e reivindicação de direitos em torno de uma determinada causa), tema que engloba o ativismo em prol da alimentação saudável e ética.', '[]', '10.7476/9786557081648', '9786557081273', 'https://books.scielo.org/id/pr3pz', NULL, NULL, 'https://books.scielo.org/id/pr3pz/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-p6ztd', 'p6ztd', 'Terceirização da gestão na Saúde Pública', NULL, '["Vaccaro, Stefania Becattini","Gomes, Thaís dos Santos"]', 'EDITORA FIOCRUZ', 'SciELO Books', 'books', 2022, NULL, 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', NULL, 'O livro busca dar visibilidade às mudanças que vêm ocorrendo no âmbito do Sistema Único de Saúde (SUS). As autoras mostram como essas mudanças do SUS estão conectadas às bases de transformações socioeconômicas do país. Em quatro capítulos, Stefania Vaccaro e Thaís dos Santos explicam as atividades estatais e as características da estrutura organizacional no Brasil, passam pelo dever estatal de promoção de saúde e pela estrutura do SUS e abordam ainda o conceito e o histórico evolutivo do fenômeno da terceirização. Por fim, elas analisam a terceirização na saúde pública, realizada por meio da contratualização com as organizações sociais de saúde (OSS). A obra examina o processo histórico de construção do SUS numa análise interdisciplinar entre direito e saúde.', '[]', '10.7476/9786557081631', '9786557081266', 'https://books.scielo.org/id/p6ztd', NULL, NULL, 'https://books.scielo.org/id/p6ztd/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-7zp2y', '7zp2y', 'Narrativas em Saúde Coletiva: memória, método e discurso', NULL, '["Ceccon, Roger Flores","Garcia-Jr., Carlos Alberto Severo","Dallmann, João Matheus Acosta","Portes, Virgínia de Menezes"]', 'EDITORA FIOCRUZ', 'SciELO Books', 'books', 2022, NULL, 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'O livro ressalta a importância da produção narrativa no campo da saúde coletiva, especialmente no contexto brasileiro. Escrita por quatro pesquisadores da Universidade Federal de Santa Catarina (UFSC), a obra se propõe a ampliar a reflexão de temas em saúde, fornecendo um panorama de conceitos e conteúdos para reafirmar a importância das narrativas no âmbito do trabalho e da educação em saúde coletiva. Em seis capítulos, os autores apostam na potência das narrativas como prática social e individual, destacando também dois componentes fundamentais no ato de narrar experiências e acontecimentos: memória e discurso. "No âmbito da pesquisa científica em saúde coletiva, o modo de narrar pode auxiliar na compreensão dos problemas relacionados a necessidades da população", afirmam.', '[]', '10.7476/9786557081617', '9786557081242', 'https://books.scielo.org/id/7zp2y', NULL, NULL, 'https://books.scielo.org/id/7zp2y/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-6r89g', '6r89g', 'O espírito das relações internacionais', NULL, '["Cervo, Amado Luiz"]', 'EDITORA UNB', 'SciELO Books', 'books', 2022, NULL, 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'Análise e interpretação de 11 comandos que conduzem e explicam o movimento dos agentes das relações internacionais pelo mundo – Estados, nações e agentes privados, sobretudo empresas, capitais e tecnologias –, este livro responde à pergunta essencial acerca do movimento das relações internacionais: quais são os impulsos de origem e como condicionam políticas, estratégias e resultados alcançados pelos agentes, por um lado, e, por outro, como esses mesmos agentes são condicionados? Ou seja: quais são os comandos superiores das relações internacionais? É um livro didático, útil para pesquisadores e estudantes da área de relações internacionais, teoria e história, e tem por objetivo a compreensão das relações internacionais no médio e no longo prazo.', '[]', '10.7476/9786558461616', '9786558461425', 'https://books.scielo.org/id/6r89g', NULL, NULL, 'https://books.scielo.org/id/6r89g/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-p4qk8', 'p4qk8', 'A pesquisa científica na era do Big Data: cinco maneiras que mostram como o Big Data prejudica a ciência, e como podemos salvá-la', NULL, '["Leonelli, Sabina"]', 'EDITORA FIOCRUZ', 'SciELO Books', 'books', 2022, NULL, 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'A partir de anos de estudos, a pesquisadora italiana Sabina Leonelli percebeu muitos vieses e diversos problemas e desafios na transformação de dados em conhecimento. O livro reúne ideias e lições extraídas dessas pesquisas, refletindo sobre como cientistas podem utilizar os chamados Big Data para atender às necessidades da sociedade e promover a integridade em pesquisa, entre outras ações. A autora mostra que, apesar dos muitos desafios, a comunidade científica pode aproveitar as potencialidades dos dados, preservando princípios éticos. A professora de Filosofia e História da Ciência da Universidade de Exeter (Reino Unido) compila, nesta obra de tema fundamental para a ciência contemporânea, observações baseadas em mais de uma década de análises das maneiras pelas quais os pesquisadores produzem, gerenciam e interpretam os dados como fontes de conhecimento.', '[]', '10.7476/9786557081600', '9786557081303', 'https://books.scielo.org/id/p4qk8', NULL, NULL, 'https://books.scielo.org/id/p4qk8/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-r3hc2', 'r3hc2', 'Os impactos sociais da Covid-19 no Brasil: populações vulnerabilizadas e respostas à pandemia', NULL, '["Gustavo Corrêa Matta","Rego, Sergio","Souto, Ester Paiva","Segata, Jean"]', 'Série Informação para ação na Covid-19 | Fiocruz eBooks', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Passados os primeiros meses da pandemia do novo coronavírus no Brasil, o Observatório Covid-19 Fiocruz, em parceria com a Editora Fiocruz e com o apoio da Rede SciELO Livros, traz para o público leitor um conjunto de livros instantâneos sobre as análises nele realizadas desde que foi criado para subsidiar o seu combate. Nesta série Informação para Ação na Covid-19 será apresentado um balanço do conjunto de documentos (notas e relatórios técnicos, boletins, ensaios, informes, recomendações, ensaios, artigos, entre outros) produzidos em resposta à pandemia. Cada volume da série se estrutura em torno de um tema: aspectos globais da pandemia e da diplomacia em saúde; cenários epidemiológicos e vigilância em saúde; as políticas e a gestão dos serviços e sistemas de saúde; orientações para os cuidados e a saúde dos trabalhadores da saúde; impactos sociais e desigualdades sociais na pandemia. Com a publicação destes estudos em livros instantâneos e de acesso aberto colocamos à disposição do público o conjunto de informações e conhecimentos gerados no âmbito do Observatório Covid-19 Fiocruz, realizamos um balanço e uma reflexão sobre como chegamos ao cenário atual e apontamos caminhos para um futuro próximo. E, ao mesmo tempo, mantemos o registro histórico desse conhecimento produzido a quente, no calor da hora.', '["COVID-19 pandemic","social impact","vulnerable populations","social inequality","pandemic response","health diplomacy","epidemiological scenarios"]', '10.7476/9786557080320', NULL, 'https://books.scielo.org/id/r3hc2', 'https://books.scielo.org/id/r3hc2/pdf/matta-9786557080320.pdf', NULL, 'https://books.scielo.org/id/r3hc2/cover/cover_thumbnail.jpeg', NULL, 156, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-76365', '76365', 'Envelhecimento, saúde e cognição humana: importância da dieta, da genética e do estilo de vida', NULL, '["Sgarbieri, Valdemiro Carlos","Bertoldo-Pacheco, Maria Teresa","Gibrim, Nádia Fátima","Oliveira, Denise Aparecida Gonçalves de","Caetano-Silva, Maria Elisa"]', 'EDITORA DA UNICAMP', 'SciELO Books', 'books', 2021, NULL, 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', NULL, 'O livro enfatiza fatores que regem a vida humana do início ao fim e que podem ser muito diferentes entre indivíduos e populações: 1) caracteres genéticos herdados diretamente de nossos pais e indiretamente de nossos ancestrais, os quais permanecem relativamente estáveis ao longo da vida; 2) fatores ambientais (alimentação, condição e estilo de vida) até certo ponto controláveis, sendo a alimentação o mais importante. A primeira parte do livro trata da definição e da conceituação do processo de envelhecimento e seus efeitos na saúde. Seguem-se a apresentação e a discussão de mecanismos que promovem degradação molecular e celular responsáveis por distúrbios metabólicos que podem resultar em doenças crônico-degenerativas. A maior parte do texto é dedicada à apresentação de alimentos e compostos bioativos que agem combatendo o envelhecimento precoce e retardando doenças da idade. Por fim, faz-se uma discussão sobre conceitos de dietas saudáveis com sugestões para pesquisas, visando melhorar o perfil alimentar do brasileiro.', '[]', '10.7476/9788526815353', '9786586253795', 'https://books.scielo.org/id/76365', NULL, NULL, 'https://books.scielo.org/id/76365/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-4txkf', '4txkf', 'Narrativas de (re)existência: antirracismo, história e educação', NULL, '["Pereira, Amilcar Araujo"]', 'EDITORA DA UNICAMP', 'SciELO Books', 'books', 2021, NULL, 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'Este livro reúne contribuições variadas para o debate sobre a importância das narrativas como conhecimento, não como mera invenção ou versão para a disputa política. Tendo em vista a riqueza e a diversidade de narrativas apresentadas, o livro foi dividido em duas partes, sendo a primeira dedicada às várias formas de pensar o antirracismo no Brasil, da perspectiva da população negra. Há narrativas literárias, históricas, políticas e audiovisuais, entre outras, que servem como ponto de partida para a construção de uma educação antirracista e democrática na sociedade brasileira. A segunda parte do livro traz diversas possibilidades de discussão sobre as narrativas de (re)existência, desde a ideia de “narrativa como evidência”, passando por narrativas de povos Rom (ciganos), na Europa, de uma liderança indígena no Brasil, de pessoas LGBTQIA+ na historiografia, e finalizando com as narrativas de professores/as em seu trabalho no ensino de História.', '[]', '10.7476/9788526815360', '9786586253894', 'https://books.scielo.org/id/4txkf', NULL, NULL, 'https://books.scielo.org/id/4txkf/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-qqbxd', 'qqbxd', 'Militância de Florestan Fernandes em defesa da escola pública brasileira (1954 – 1964)', NULL, '["Netto, Mário Borges"]', 'EDUEM', 'SciELO Books', 'books', 2021, NULL, 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'Esta obra trata da ação intelectual de Florestan Fernandes no campo educacional, no período de 1954 a 1964, quando da sua militância como intelectual em defesa da educação pública no contexto da elaboração e tramitação da LDB nº 4.024, de 1961. Sociólogo de formação, um dos principais estudiosos da constituição da sociedade e do capitalismo brasileiro, legítimo intelectual orgânico dos grupos subalternos, Florestan Fernandes ficou marcado na historiografia da educação brasileira por seu envolvimento ativo e persistente na luta pela escolarização dos filhos da classe trabalhadora.', '[]', '10.7476/9786587626093', '9786586383911', 'https://books.scielo.org/id/qqbxd', NULL, NULL, 'https://books.scielo.org/id/qqbxd/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-dpt69', 'dpt69', 'Estudios de la tuberculosis desde la Sucursal del Cielo', NULL, '[]', 'EDITORIAL UNIVERSIDAD SANTIAGO DE CALI', 'SciELO Books', 'books', 2021, NULL, 'es', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', NULL, 'Este libro está dirigido a la comunidad académica, científica y en general a aquellas personas interesadas en ampliar sus conocimientos sobre la tuberculosis. Iniciamos con una revisión general de la evolución de las metodologías diagnósticas. Posteriormente, destacamos diferentes trabajos de investigación realizados en Cali y el Valle del Cauca en torno a la tuberculosis, resaltando herramientas empleadas para la vigilancia epidemiológica de la enfermedad, así como el estudio de la tuberculosis en población vulnerable (tuberculosis infantil y la incidencia de esta enfermedad en trabajadores de la salud en los últimos años en Cali). Este libro resalta la necesidad de entender el enfoque humano que rodea esta enfermedad, en esa dirección los dos últimos capítulos los enfocamos en las creencias sobre la tuberculosis y la interacción del paciente con las entidades prestadoras de servicios de salud. Esperamos que nuestro libro genere importantes aportes a aquellos que se involucran en el estudio de esta enfermedad que ha acompañado al hombre probablemente desde su presencia en el planeta y sea, además, el insumo de futuros investigadores en las diversas áreas del conocimiento que confluyen en el entendimiento de esta enfermedad infecciosa.', '[]', NULL, '9789585147249', 'https://books.scielo.org/id/dpt69', 'https://books.scielo.org/id/dpt69/pdf/nieto-9786287501669.pdf', 'https://books.scielo.org/id/dpt69/epub/nieto-9786287501669.epub', 'https://books.scielo.org/id/dpt69/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-fmb5z', 'fmb5z', 'A (des)patologização do processo de escolarização: contribuições da psicologia histórico-cultural', NULL, '["Leonardo, Nilza Sanches Tessaro","Silva, Silvia Maria Cintra da","Leal, Záira Fátima de Rezende Gonzalez"]', 'EDUEM', 'SciELO Books', 'books', 2021, NULL, 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'Considera-se relevante a presente coletânea por aglomerar e apresentar estudos e pesquisas que tratam sobre a patologização e medicalização do processo de escolarização, a partir dos pressupostos teóricos da Psicologia Histórico-Cultural. Busca contribuir para a construção de reflexões e compreensões que abram possibilidades de contraposição às concepções hegemônicas sobre os problemas no processo de escolarização, concepções estas que partem de um viés biologicista e patologizante que culmina na medicalização da educação.', '[]', '10.7476/9786587626086', '9786587626048', 'https://books.scielo.org/id/fmb5z', NULL, NULL, 'https://books.scielo.org/id/fmb5z/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-2kv6c', '2kv6c', 'Caleidoscópio Primo Levi: ensaios sobre um poliédrico quimiscritor', NULL, '["Maciera, Aislan Camargo","Massi, Luciana"]', 'EDITORA DA UNICAMP', 'SciELO Books', 'books', 2021, NULL, 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'Primo Levi (1919-1987), italiano de origem judaica, químico, sobrevivente dos campos de concentração e extermínio nazistas, é considerado um dos principais nomes da literatura que surge da experiência nos campos de concentração. Através de sua literatura, promove uma reflexão não somente sobre a Shoah, mas também sobre a própria condição humana. Mas, muito além do testemunho, a obra de Levi se constitui em uma complexidade de temas e gêneros, o que o torna um autor poliédrico. Nessa perspectiva, o objetivo desta coletânea é apresentar as várias faces desse poliedro, partindo de seu testemunho, passando pela ficção, pela fantasia, pelo romance, pelos ensaios críticos e escritos de divulgação científica, para formar, em sua totalidade, a imagem de um dos mais significativos pensadores do século XX, que ainda tem muito a dizer ao leitor do século XXI.', '[]', '10.7476/9788526815391', '9786586253887', 'https://books.scielo.org/id/2kv6c', NULL, NULL, 'https://books.scielo.org/id/2kv6c/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-tmdpt', 'tmdpt', 'Ecologia política: da desconstrução do capital à territorialização da vida', NULL, '["Leff, Enrique"]', 'EDITORA DA UNICAMP', 'SciELO Books', 'books', 2021, NULL, 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'As concepções capitalistas de progresso com crescimento sem limites da economia conduziram o planeta a uma crise ambiental sem precedentes. A ecologia política visa desconstruir essa racionalidade insustentável e impulsionar ações sociais para a construção de um futuro sustentável, reorientando o desenvolvimento das forças produtivas, recriando as formas de sociabilidade e reconfigurando as relações de poder. Esse pensamento tem ressonâncias no campo da produção e do conhecimento, da política e das práticas educativas. O ambientalismo radical confronta o poder hegemônico unificador do mercado como destino inelutável da humanidade e valoriza a diversidade cultural, os saberes tradicionais e os direitos humanos, fundando um pensamento emancipatório e uma ética política para renovar o sentido da vida e defender a preservação da natureza.', '[]', '10.7476/9788526815414', '9786586253627', 'https://books.scielo.org/id/tmdpt', NULL, NULL, 'https://books.scielo.org/id/tmdpt/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-dy7z7', 'dy7z7', 'Imagem: diálogos e interfaces interdisciplinares', NULL, '["Silva, Josie Agatha Parrilha da","Neves, Marcos Cesar Danhoni"]', 'EDUEM', 'SciELO Books', 'books', 2021, NULL, 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'O livro Imagem: diálogos e interfaces interdisciplinares nasceu da ideia desenvolvida por um grupo de docentes da Universidade Estadual de Ponta Grossa, ao estabelecer diálogos sobre o tema Imagem entre diferentes áreas de conhecimento. As imagens se fazem presentes de forma significativa no cotidiano humano e a pesquisa em torno delas possibilita novas formas de comunicações, interpretações e estéticas diferenciadas, alicerçadas em fundamentos, teorias e práticas que requeiram um domínio visual próprio e a busca ininterrupta dos sentidos definidores do próprio conhecimento. Assim, a Imagem foi o tema gerador escolhido para realizar reflexões interdisciplinares teórico-práticas que contribuirão para a construção de um conhecimento que supere as fronteiras disciplinares. Importante destacar que cada área de conhecimento possui distintas concepções e formas de abordar a Imagem. Tal pressuposto justifica as diferentes metodologias adotadas no decorrer dos capítulos do livro. Na estrutura da obra apresentaremos, de um lado, distintas metodologias provenientes de diferentes áreas, e de outro, novas possibilidades de refletir crítica, teórica e metodologicamente sobre estudos, pesquisas e produções ligados à Imagem. O livro apresenta discussões que remontam à década de 1980 e de discussões atuais, de pesquisadores nacionais e internacionais. O livro pode ser fonte de estudos interdisciplinares sobre Imagem, tanto em nível de graduação quanto de pós-graduação.', '[]', '10.7476/9786587626079', '9786586383898', 'https://books.scielo.org/id/dy7z7', 'https://books.scielo.org/id/dy7z7/pdf/silva-9786587626079.pdf', 'https://books.scielo.org/id/dy7z7/epub/silva-9786587626079.epub', 'https://books.scielo.org/id/dy7z7/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-mw25s', 'mw25s', 'Semiótica e pragmatismo: interfaces teóricas: vol. 2', NULL, '["Ibri, Ivo Assad"]', 'EDITORA UNESP', 'SciELO Books', 'books', 2021, NULL, 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, '“Este segundo volume de ensaios de Ivo Ibri transborda com insights esclarecedores do início ao fim. Ele consegue revelar muitos aspectos do pensamento de Peirce de ângulos que a pesquisa acadêmica tradicional não fora equipada para perceber. Como não perder tais oportunidades teóricas kairóticas e como explorá-las com vantagens heurísticas é uma lição bem ensinada neste excelente livro. A dívida de gratidão da pesquisa acadêmica para com o autor só pode ser paga com o aprendizado dessa lição.” André De Tienne (Indiana University / USA).', '[]', NULL, '9786559541270', 'https://books.scielo.org/id/mw25s', 'https://books.scielo.org/id/mw25s/pdf/ibri-9786559541287.pdf', 'https://books.scielo.org/id/mw25s/epub/ibri-9786559541287.epub', 'https://books.scielo.org/id/mw25s/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-9nk5n', '9nk5n', 'A Itália em disputa: comunistas e democratas-cristãos no longo pós-guerra (1943-1978)', NULL, '["Vacca, Giuseppe"]', 'EDITORA DA UNICAMP', 'SciELO Books', 'books', 2021, NULL, 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', NULL, 'A história narrada neste livro é excepcional. São 35 anos da vida política italiana após o fascismo e a guerra. Instalada a República, veio em seguida a luta pela reconstrução e pela modernização do país. Com o passar dos anos, alteraram-se sobremaneira as estruturas do país e a sociabilidade dos italianos. Essa grande epopeia se fez por meio de uma dinâmica política marcada pelo embate e, ao mesmo tempo, pelo consenso entre a Democracia Cristã e o Partido Comunista, duas forças populares e opostas. O que dava sustentação ao sistema político não era a oposição entre direita e esquerda, mas uma dupla legitimação: o antifascismo, base do “campo” democrático, e o anticomunismo, imprescindível para governar em tempos de Guerra Fria. Vacca analisa a fase ascendente da democracia italiana, da Liberazione à morte de Aldo Moro, para muitos um marco do seu bloqueio e o início do longo declínio. (Alberto Aggio)', '[]', '10.7476/9788526815377', '9786586253948', 'https://books.scielo.org/id/9nk5n', NULL, NULL, 'https://books.scielo.org/id/9nk5n/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-6djz9', '6djz9', 'África, margens e oceanos: perspectivas de história social', NULL, '["Reginaldo, Lucilene","Ferreira, Roquinaldo"]', 'EDITORA DA UNICAMP', 'SciELO Books', 'books', 2021, NULL, 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'Desde meados dos anos 2000, a produção africanista brasileira vem destacando-se no cenário internacional por suas contribuições originais. Este livro apresenta alguns desses aportes, tais como a ênfase na história social e o protagonismo de atores africanos. Ao mesmo tempo, destaca as referências intelectuais e os contornos sociais que demarcam a produção sobre história da África no Brasil, evidenciando a relevância dos estudos sobre o tráfico, o interesse pelas experiências dos escravizados e as demandas dos movimentos negros na sua constituição. Coloca em relevo também os diálogos estabelecidos com a historiografia africanista estrangeira, seja ela produzida em centros de pesquisa norte-americanos, europeus ou africanos. Além disso, explora os limites e alarga os horizontes das pesquisas realizadas no Brasil, chamando atenção para temas e cenários ainda pouco explorados, notadamente as conexões do Índico com a África, as Américas e a Ásia. Por fim, mas não menos importante, aborda questões relativas ao ensino de história da África, enfatizando sua relação com os estudos acadêmicos e com as políticas públicas de combate ao racismo no Brasil.', '[]', '10.7476/9788526815339', '9786586253665', 'https://books.scielo.org/id/6djz9', NULL, NULL, 'https://books.scielo.org/id/6djz9/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-n5g9r', 'n5g9r', 'Carta de achamento do Brasil', NULL, '["Caminha, Pero Vaz de"]', 'EDITORA DA UNICAMP', 'SciELO Books', 'books', 2021, NULL, 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'Escrita em maio de 1500 em Porto Seguro, Bahia, a carta do escrivão Pero Vaz de Caminha ao rei D. Manuel assemelha-se a um relato de viagem. Mais do que descrever a terra e a natureza, brevemente vistas durante os nove dias em que a frota de Pedro Álvares Cabral esteve no que viria a ser o Brasil, a narrativa é centrada nos povos indígenas, e as palavras de Caminha, hábil escritor, pintam imagens vívidas do que observou, pretendendo informar e maravilhar o seu interlocutor. A “Carta” nos surpreende com questões que até hoje, mais de 500 anos depois, permanecem agudamente presentes, tais como a ameaça da mineração aos povos indígenas, o direito à propriedade da terra e o apagamento de vozes não europeias. Nesta edição modernizada, uma introdução contextualiza a carta em seu tempo, destaca sua singularidade e aponta as apropriações culturais e políticas que dela se fizeram. As notas explicam o texto passo a passo, abrindo caminhos para uma interpretação atualizada e crítica.', '[]', '10.7476/9788526815469', '9786586253825', 'https://books.scielo.org/id/n5g9r', NULL, NULL, 'https://books.scielo.org/id/n5g9r/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-vvcgn', 'vvcgn', 'Humanidades e ciências naturais: ensaios e balanços críticos', NULL, '["Barreto, Márcio"]', 'EDITORA DA UNICAMP', 'SciELO Books', 'books', 2021, NULL, 'pt', 'book', 'humanities', 'Humanidades y Artes', NULL, 'Sociedade de controle, big data, data science, sociedade da informação, cidades inteligentes, internet das coisas, inteligência artificial, datificação, sociedade de risco, tecnologia social, engenharia genética pertencem a que área do conhecimento? A especialização e a fragmentação do saber em áreas e subáreas estão em xeque, pois a complexidade das grandes questões contemporâneas rompe as fronteiras que separam natureza e cultura, arte e técnica, ambiente e sociedade, entre outras dualidades estabelecidas pelo hábito disciplinar. Humanidades e ciências naturais: ensaios e balanços críticos destina-se principalmente a cursos de graduação de ciências exatas e biológicas que têm em sua grade curricular disciplinas de humanidades, mas também é indicado para cursos de ciências humanas que pretendem um diálogo com as outras áreas do conhecimento.', '[]', '10.7476/9788526815452', '9786586253689', 'https://books.scielo.org/id/vvcgn', NULL, NULL, 'https://books.scielo.org/id/vvcgn/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-kng2j', 'kng2j', 'Fascismo e grande capital', NULL, '["Guérin, Daniel"]', 'EDITORA DA UNICAMP', 'SciELO Books', 'books', 2021, NULL, 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', NULL, 'Fascismo e grande capital é um clássico. Publicado em 1936, foi editado e reeditado em diversos países. No Brasil, permanecia inédito. O autor viajara pela Alemanha nazista e escrevera um livro relatando essa viagem. Impressionada com a qualidade do material, uma companheira o incitou a fazer uma pesquisa sistemática sobre o tema. O resultado foi este livro repleto de ideias, de teses originais e também de tratamento mais fundamentado e desenvolvido para teses que já circulavam sobre o fascismo. O objetivo de Fascismo e grande capital é elaborar o conceito de fascismo. Para tal elaboração conceitual, o autor examina o fascismo na Itália e na Alemanha. Guérin apresenta o fascismo como um movimento pequeno-burguês e de classe média, reacionário, que, numa conjuntura determinada, é cooptado pela burguesia e, particularmente, pela grande burguesia, que disputa a hegemonia política com o médio capital. O livro de Daniel Guérin, tratando de fenômeno aparentemente tão distante, contribui para a compreensão da natureza da extrema direita no mundo contemporâneo. (Armando Boito Jr.)', '[]', '10.7476/9788526815421', '9786586253931', 'https://books.scielo.org/id/kng2j', NULL, NULL, 'https://books.scielo.org/id/kng2j/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-q6ggp', 'q6ggp', 'Educação e gestão neoliberal: a escola cooperativa de Maringá – uma experiência de Charter School?', NULL, '["Azevedo, Mário Luiz Neves de"]', 'EDUEM', 'SciELO Books', 'books', 2021, NULL, 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'Elegemos como objeto central deste livro a relação entre educação e neoliberalismo. Nosso objetivo principal é de conhecer suas origens, descobrir a que veio, discutir sobre as causas da sua aceitação geral e identificar as suas propostas para a educação. O mercado é o instrumento de (des)regulação da economia nomeado pelo neoliberalismo. Os doutrinadores neoliberais imaginam um mercado perfeito. Desejam que ele evite as crises, equilibre a oferta e a procura e aloque eficientemente os recursos. Pode-se analisar esse movimento de diferentes perspectivas. Por uma delas, o neoliberalismo é visto como mais uma representação da falsa consciência expressa pelas classes dominantes ou por frações destas classes. Desse ponto de vista, considera-se que essa falsa interpretação é imposta ao complexo social como se fosse uma leitura verdadeira da realidade. Por outro lado, entretanto, pode-se considerar que há uma “razão real” que justifica e respalda o neoliberalismo. Isto é, devido às deficiências do Estado “realmente existente” no atendimento ao público e em virtude da essência estatal já estar privatizada, as reformas propostas pelos neoliberais são aceitas sem maiores resistências pela população. Não obstante o discurso feito pelos neoliberais de que a educação é das poucas áreas onde o Estado que continuar sendo atendida pelo Estado, na realidade, esse patrocínio estatal, também, passa pelo mercado. As propostas para a educação elaboradas por Milton Friedman, referência inconteste do neoliberalismo, e a experiência privatizante do ensino de primeiro grau ocorrida no Município de Maringá são objetos de análise no presente trabalho.', '[]', '10.7476/9786587626062', '9786587626055', 'https://books.scielo.org/id/q6ggp', 'https://books.scielo.org/id/q6ggp/pdf/azevedo-9786587626062.pdf', 'https://books.scielo.org/id/q6ggp/epub/azevedo-9786587626062.epub', 'https://books.scielo.org/id/q6ggp/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W3015145497', 'https://openalex.org/W3015145497', '“Pandemic fear” and COVID-19: mental health burden and strategies', NULL, '["Felipe Rech Ornell","Jaqueline Bohrer Schuch","Anne Orgler Sordi","Félix Henrique Paim Kessler"]', 'Brazilian Journal of Psychiatry', 'SciELO Brasil', 'scielo-br', 2020, '2020-04-04', 'en', 'article', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Documento científico en Acceso Abierto (Psychology) publicado en Brazilian Journal of Psychiatry.', '["COVID-19 pandemic","pandemic fear","mental health burden","psychological distress","coping strategies","anxiety"]', '10.1590/1516-4446-2020-0008', NULL, 'https://doi.org/10.1590/1516-4446-2020-0008', 'https://www.scielo.br/j/rbp/a/WGD9CnJ95C777tcjnkHq4Px/?lang=en&format=pdf', NULL, NULL, NULL, 1995, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W3024365698', 'https://openalex.org/W3024365698', 'Niveles de estrés, ansiedad y depresión en la primera fase del brote del COVID-19 en una muestra recogida en el norte de España', NULL, '["Naiara Etxebarria","María Dosil Santamaría","Maitane Picaza-Gorrochategui","Nahia Idoiaga-Mondragon"]', 'Cadernos de Saúde Pública', 'SciELO Brasil', 'scielo-br', 2020, '2020-01-01', 'es', 'article', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'En marzo de 2020, el virus SARS-CoV-2 procedente de China ha llegado a España y desde el 14 de marzo se ha declarado el estado de alarma en todo el Estado español, llevando al confinamiento a toda la población. La presente investigación se contextualiza en la Comunidad Autónoma Vasca (situada al norte de España). Se han analizado los niveles de estrés, ansiedad y depresión a la llegada del virus y se han estudiado los niveles de sintomatología psicológica según edad, cronicidad y confinamiento. Se ha recogido una muestra de 976 personas y la medición de las variables ansiedad, estrés y depresión se ha hecho mediante la escala DASS (Escala de Depresión, Ansiedad y Estrés). Los resultados demuestran que, aunque los niveles de sintomatología han sido bajos en general al principio de la alarma, la población más joven y con enfermedades crónicas ha referido sintomatología más alta que el resto de población. También se ha detectado un mayor nivel de sintomatología a partir del confinamiento, donde las personas tienen prohibido salir de sus casas. Se prevé que la sintomatología aumentará según vaya transcurriendo el confinamiento. Se defienden intervenciones psicológicas de prevención y tratamiento para bajar el impacto psicológico que pueda crear esta pandemia.', '["COVID-19 pandemic","psychological stress","anxiety","depression","lockdown","state of alarm","chronic disease"]', '10.1590/0102-311x00054020', NULL, 'https://doi.org/10.1590/0102-311x00054020', 'https://www.scielo.br/j/csp/a/bnNQf4rdcMNpPjgfnpWPQzr/?lang=es&format=pdf', NULL, NULL, NULL, 1135, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-6rj47', '6rj47', 'Diálogos interdisciplinarios sobre los problemas de la justicia en Colombia', NULL, '[]', 'EDITORIAL UNIVERSIDAD DEL ROSARIO', 'SciELO Books', 'books', 2020, NULL, 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'El acceso a la justicia y a las problemáticas que la rodean no deja de ser un hecho pertinente ante la realidad del país. Son múltiples las barreras existentes no solo para acceder al aparato judicial, sino también para garantizar el correcto ejercicio de los derechos humanos. Por lo anterior, la Universidad del Rosario, en cabeza del Observatorio Legislativo y del Grupo de Investigación en Derechos Humanos, en asociación con la Fundación Hanns Seidel, culminó con éxito la décima versión del Concurso Nacional de Semilleros de Investigación titulado “Diálogos interdisciplinarios sobre los problemas de la justicia en Colombia”, el cual, por primera vez en la historia, se realizó de manera virtual, dadas las circunstancias generadas por la pandemia COVID-19. El cierre del evento fue aún más contundente con la publicación de este libro, que contiene las ponencias de los estudiantes ganadores. En esta oportunidad, el objetivo del concurso fue brindar un espacio propicio de investigación, generación de conocimiento y fortalecimiento de habilidades para los estudiantes interesados en reflexionar en torno al acceso a la justicia y sus barreras desde diferentes frentes: estructura institucional; grupos de especial protección constitucional; eficacia, eficiencia y transparencia; métodos alternativos en resolución de conflictos; justicia diferencial; justicia en los territorios; jurisdicciones especiales y justicia digital.', '[]', NULL, '9789587845600', 'https://books.scielo.org/id/6rj47', 'https://books.scielo.org/id/6rj47/pdf/torres-9789587845617.pdf', 'https://books.scielo.org/id/6rj47/epub/torres-9789587845617.epub', 'https://books.scielo.org/id/6rj47/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-trn8b', 'trn8b', 'De la ética a la bioética en las ciencias de la salud', NULL, '[]', 'EDITORIAL UNIVERSIDAD SANTIAGO DE CALI', 'SciELO Books', 'books', 2020, NULL, 'es', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', NULL, 'Cada capítulo va dedicado por los autores/as a profesionales hombres y mujeres que quieren profundizar en la temática del libro: ética y bioética en diversas disciplinas sanitarias, para conocer y respetar a cabalidad el cumplimiento de los códigos y la normatividad, en espacios en los que les corresponde su accionar y a quienes en una u otra orilla cumplen con sus debe- res y defienden sus derechos en pro de la dignidad humana. En los escritos se evidencia que sus aportes se derivan de sus estudios, de sus lecturas, de su experiencia, de sus relaciones dialógicas en la práctica clínica y saberes académicos en su trayectoria como docentes en Educación Superior. Con la compilación de estos escritos se demuestra que el trabajo interdisciplinario permite la construcción de nuevos conocimientos por medio de la investigación, dando lugar a reflexiones sobre la ética y la moral de los profesionales de la salud, en busca del respeto por la integralidad del ser humano. “Atravesemos el puente de la praxis bioética, que nos conduzca a la orilla de la Esperanza humana”. −Myriam Bermeo de Rubio.', '[]', NULL, '9789585147737', 'https://books.scielo.org/id/trn8b', 'https://books.scielo.org/id/trn8b/pdf/bermeo-9786287501638.pdf', 'https://books.scielo.org/id/trn8b/epub/bermeo-9786287501638.epub', 'https://books.scielo.org/id/trn8b/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-wmjmm', 'wmjmm', 'El procedimentalismo en la formación ético-discursiva profesional', NULL, '["Muñoz Joven, Luis Armando"]', 'EDITORIAL UNIVERSIDAD SANTIAGO DE CALI', 'SciELO Books', 'books', 2020, NULL, 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'El ser humano en el curso de su vida aprenderá diferentes comportamientos que se convertirán en hábitos que impactarán directamente en su estilo de vida; la adolescencia y la adultez joven son momentos particularmente decisivos en el afianzamiento de éstos, los cuales serán determinantes para el desarrollo o no de enfermedades no transmisibles en su adultez y vejez.', '[]', NULL, '9789585583894', 'https://books.scielo.org/id/wmjmm', 'https://books.scielo.org/id/wmjmm/pdf/munoz-9786287501645.pdf', 'https://books.scielo.org/id/wmjmm/epub/munoz-9786287501645.epub', 'https://books.scielo.org/id/wmjmm/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-wrdxb', 'wrdxb', 'Conflictos indígenas ante la justicia colonial: los hilos entrelazados de una compleja trama social y legal, siglos XVI-XVII', NULL, '[]', 'EDITORIAL UNIVERSIDAD SANTIAGO DE CALI', 'SciELO Books', 'books', 2020, NULL, 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'Este texto compilatorio recoge distintas investigaciones que giran en torno a la relación entre los pueblos indígenas con la corona hispánica en el periodo colonial. A través de distintos estudios de caso en los niveles locales y regionales, estos escritos indagan sobre problemas tales como la agencia histórica y social indígena, la hegemonía del poder político y las estrategias de los actores para afrontar los desafíos de su vida particular y colectiva. La justicia, el orden social y los conflictos son los marcos de estas historias entrelazadas, que contribuyen a una comprensión más específica y problemática sobre dichos pasados en la América Hispánica.', '[]', '10.7476/9786287501676', '9789585147607', 'https://books.scielo.org/id/wrdxb', 'https://books.scielo.org/id/wrdxb/pdf/cuevas-9786287501676.pdf', 'https://books.scielo.org/id/wrdxb/epub/cuevas-9786287501676.epub', 'https://books.scielo.org/id/wrdxb/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W2952846235', 'https://openalex.org/W2952846235', 'Fundamentos Epistémicos de la Investigación Cualitativa y Cuantitativa: Consensos y Disensos', NULL, '["Fabio Anselmo Sánchez-Flores"]', 'Revista Digital de Investigación en Docencia Universitaria', 'Red SciELO', 'scielo-network', 2019, '2019-04-24', 'es', 'article', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'En el presente artículo se analizan las principales características de la investigación con enfoque cuantitativo y cualitativo, contrastando sus diferencias y señalando sus semejanzas tanto históricas y epistémicas como metodológicas y procedimentales. Asimismo, se define su pertinencia dependiendo de la temática de estudio y de la disciplina –científica, protocientífica o humana– en la que se enmarque, brindando pautas para la elección de uno u otro enfoque, o de ambos –investigación mixta–, a través de la ponderación de sus ventajas y desventajas para la investigación científica. Por otro lado, se destaca la importancia de establecer canales de comunicación e integración entre sendos enfoques cognoscitivos, lejos de las concepciones que pretenden encontrar disensos más que consensos, contraviniendo así el valor de los estudios con enfoque mixto o complementario, que sería uno alternativo a los anteriores, mas no por ello superior ni siempre necesario.', '["epistemology of research","qualitative research","quantitative research","mixed methods","research methodology selection","human sciences"]', '10.19083/ridu.2019.644', NULL, 'https://doi.org/10.19083/ridu.2019.644', 'https://revistas.upc.edu.pe/index.php/docencia/article/download/644/913', NULL, NULL, NULL, 1765, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W2909539792', 'https://openalex.org/W2909539792', 'Investigación cualitativa: Método fenomenológico hermenéutico', NULL, '["Doris Fuster-Guillén"]', 'Propósitos y Representaciones', 'Red SciELO', 'scielo-network', 2019, '2019-01-01', 'es', 'article', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este artículo presenta nociones fundamentales de uno de los métodos de investigación cualitativa, nos referimos a la fenomenología hermenéutica sustentada en las teorías de Van Manen, Raquel Ayala y Miguel Martínez. Este enfoque conduce a la descripción e interpretación de la esencia de las experiencias vividas, reconoconoce el significado y la importacia en la pedagogía, psicología y sociología según la experiencia recogida. Este método constituye procesos rigurosos y coherentes de las dimensiones éticas de la experiencia cotidiana, difícilmente accesibles por otros métodos usuales de investigación. En esta contribución, se presenta algunas nociones metodológicas centradas en los principios de la fenomenología y sus fases: etapa previa o clarificación de presupuestos, recoger la experiencia vivida, reflexionar acerca de la experiencia vivida o etapa estructural y, finalmente, escribir-reflexionar acerca de la experiencia vivida evidenciada en fisonomía individual y grupal o llamada también texto fenomenológico.', '["hermeneutic phenomenology","lived experience","van Manen","lived experience research","meaning of experience","qualitative research methodology","reflective writing"]', '10.20511/pyr2019.v7n1.267', NULL, 'https://doi.org/10.20511/pyr2019.v7n1.267', 'https://revistas.usil.edu.pe/index.php/pyr/article/download/267/615', NULL, NULL, NULL, 1505, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-mxmfw', 'mxmfw', 'Colombia frente a los Objetivos de Desarrollo Sostenible: retos desde los derechos humanos', NULL, '[]', 'EDITORIAL UNIVERSIDAD DEL ROSARIO', 'SciELO Books', 'books', 2019, NULL, 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'Próximos a cumplir el primer quinquenio de los quince años previstos para alcanzar el máximo resultado en la realización de los Objetivos de Desarrollo Sostenible (ODS), la Universidad del Rosario, en cabeza del Observatorio Legislativo y el Grupo de Investigación en Derechos Humanos, en asociación con la Fundación Hanns Seidel, ha brindado el espacio propicio de investigación para los estudiantes interesados en reflexionar, discutir y proponer trabajos académicos relacionados con los ODS. Así, este libro recoge las ponencias de los estudiantes ganadores del IX Concurso de Semilleros de Investigación, en procura de propiciar espacios académicos de fortalecimiento de la democracia, la institucionalidad y los derechos humanos, dentro de los cuales este concurso se destaca no solo por perdurabilidad en el tiempo, al atender temas coyunturales para el país, sino por la pertinencia de dar valor a la investigación como herramienta de cambio social y como instrumento pedagógico de enseñanza que debe fomentarse en la educación superior.', '[]', NULL, '9789587843491', 'https://books.scielo.org/id/mxmfw', 'https://books.scielo.org/id/mxmfw/pdf/torres-9789587843507.pdf', 'https://books.scielo.org/id/mxmfw/epub/torres-9789587843507.epub', 'https://books.scielo.org/id/mxmfw/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W3037124493', 'https://openalex.org/W3037124493', 'Princípios de fertilidade do solo, adubação e nutrição mineral', NULL, '["Marcelo Augusto Batista","Tadeu Takeyoshi Inoue","Michel Esper Neto","Antônio Saraiva Muniz"]', 'SciELO Network', 'Red SciELO', 'scielo-network', 2018, '2018-01-01', 'pt', 'chapter', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'IntroduçãoO estudo da fertilidade do solo, dos fertilizantes, da adubação e da nutrição mineral de plantas tem sido abordado por vários autores brasileiros e internacionais de forma extensiva e completa.Dessa forma, o objetivo deste capítulo é abordar, sucintamente, os principais aspectos envolvidos para o conhecimento do solo, dos fertilizantes e da nutrição mineral para o bom desenvolvimento de hortaliças-fruto de forma geral.A demanda de nutrientes por este grupo de plantas é alta, sendo necessário, para produções substanciais, o uso adicional de fertilizantes orgânicos e minerais.Contudo esse uso pode dar-se de forma desordenada, com adubação excessiva, podendo resultar em desequilíbrios, caracterizados pelo excesso de alguns nutrientes e/ou deficiência de outros.Isso acarreta prejuízos financeiros por gastos desnecessários, baixas produções e produtos com menor qualidade nutricional e visual.O uso desordenado de fertilizantes pode também trazer problemas ambientais, como contaminação do solo e da água dos lençóis freáticos, mananciais, nascentes, córregos e rios.Assim, o conhecimento do solo, da capacidade de este fornecer nutrientes e água para as plantas e a demanda nutricional das mesmas são quesitos indispensáveis para o uso adequado dos recursos naturais, a fim de obter as melhores respostas em crescimento e em desenvolvimento das culturas, além de considerar os aspectos econômicos e socioambientais.Os nutrientes no solo apresentam comportamentos diversos, e o conhecimento das especificidades de cada um possibilita a previsão desses comportamentos em cada cenário de manejo.Os nutrientes que se encontram no solo podem seguir diversas rotas, tais como: serem perdidos por erosão, lixiviação, volatilização, fixação nas argilas do solo, imobilização e absorvidos pelas plantas, desempenhando, nesse caso, seu principal papel.Associado a isso, a exportação dos nutrientes absorvidos pelas culturas juntamente com o produto para fora das áreas de cultivo contribuem para aumentar a complexidade às suas dinâmicas.Dessa forma, este capítulo abordará questões associadas aos conceitos sobre a química da sorção dos nutrientes catiônicos e aniônicos no solo, a apresentação de cada um dos macro e micronutrientes, informando os principais tópicos associados à dinâmica do nutriente no solo e na planta e, por último, discussões sobre os principais fertilizantes e as formas de adubação.Frações do solo Dimensões (mm) Areia Grossa 2-0,2 Areia Fina 0,2-0,05 Silte 0,05-0,002 Argila < 0,002 ou 2 µm Coloides < 0,001 ou 1 µm Fonte: Van Lier (2010).', '["soil fertility","fertilization","plant mineral nutrition","vegetable crops","fruit crops","nutrient requirements","nutrient availability"]', '10.7476/9786586383010.0006', NULL, 'https://doi.org/10.7476/9786586383010.0006', 'https://doi.org/10.7476/9786586383010.0006', NULL, NULL, NULL, 44, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-nw2rh', 'nw2rh', 'Agroclimatología del Ecuador', NULL, '["Fredi Leonidas Portilla Farfán"]', 'SciELO Network', 'SciELO Books', 'books', 2018, '2018-01-01', 'es', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'La climatología indudablemente es una ciencia aplicable a todas las áreas del conocimiento y en este caso de enorme trascendencia para el área de la Ingeniería Agronómica, Ambiental y afines. El presente trabajo constituye una aproximación a la climatología del Ecuador continental e insular en base de datos oficiales que propende servir a futuro para estudios de aplicación en el área de ciencias de la vida. Los estudios relativos al clima del Ecuador regularmente han estado enfocados al sector turístico, área importante de desarrollo; sin embargo es menester estructurar una climatología que tenga aplicación en el área agropecuaria y ambiental, fuente de autoconsumo y de generación de divisas. No se encuentra, sin embargo, una climatología estadística sistemática del Ecuador que permita situarse con una cierta amplitud en el contexto de un estudio climático del conjunto del país. A partir de datos oficiales proporcionados por el INAMHI (Instituto Nacional de Meteorología e Hidrología del Ecuador), el presente trabajo tiene como objetivo formular una climatología estadística básica que nos permita afrontar trabajos más específicos posteriormente.', '["agroclimatology","agrometeorology"]', '10.7476/9789978104927', NULL, 'https://books.scielo.org/id/nw2rh', 'https://books.scielo.org/id/nw2rh/pdf/portilla-9789978104927.pdf', NULL, 'https://books.scielo.org/id/nw2rh/cover/cover_thumbnail.jpeg', NULL, 16, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W2607403110', 'https://openalex.org/W2607403110', 'Técnicas de Muestreo sobre una Población a Estudio', NULL, '["Támara Otzen","Carlos Manterola"]', 'International Journal of Morphology', 'Red SciELO', 'scielo-network', 2017, '2017-03-01', 'es', 'article', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Mathematics', 'RESUMEN: La representatividad de una muestra, permite extrapolar y por ende generalizar los resultados observados en ésta, a la población accesible; y a partir de ésta, a la población blanco.Por ende, una muestra será representativa o no; sólo si fue seleccionada al azar, es decir, que todos los sujetos de la población blanco tuvieron la misma posibilidad de ser seleccionados en esta muestra y por ende ser incluidos en el estudio; y por otro lado, que el número de sujetos seleccionados representen numéricamente a la población que le dio origen respecto de la distribución de la variable en estudio en la población, es decir, la estimación o cálculo del tamaño de la muestra.Es así como el análisis de una muestra permite realizar inferencias, extrapolar o generalizar conclusiones a la población blanco con un alto grado de certeza; de tal modo que una muestra se considera representativa de la población blanco, cuando la distribución y valor de las diversas variables se pueden reproducir con márgenes de error calculables.Entonces, el muestreo tiene por objetivo estudiar las relaciones existentes entre la distribución de una variable en la población blanco y las distribución de ésta variable en la muestra a estudio.Para ello, es fundamental, entre otras cosas definir los criterios de inclusión (características clínicas, demográficas, temporales y geográficas de los sujetos que componen la población en estudio) y de exclusión (características de los sujetos que pueden interferir con la calidad de los datos o la interpretación de los resultados.El objetivo de este manuscrito, es entregar conocimientos generales respecto de las técnicas de muestreo más utilizadas en investigación clínica.', '["sampling methods","sample representativeness","random sampling","sample size determination","inclusion and exclusion criteria","clinical research","statistical inference"]', '10.4067/s0717-95022017000100037', NULL, 'https://doi.org/10.4067/s0717-95022017000100037', 'https://scielo.conicyt.cl/pdf/ijmorphol/v35n1/art37.pdf', NULL, NULL, NULL, 3955, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W2890527020', 'https://openalex.org/W2890527020', 'La investigación en educación', NULL, '["María Josefa Mosteiro García","Ana María Porto Castro"]', 'SciELO Network', 'Red SciELO', 'scielo-network', 2017, '2017-01-01', 'pt', 'chapter', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'origen y evoluciónLa investigación educativa es una disciplina relativamente reciente.Su origen está marcado por la aparición de la pedagogía experimental en el siglo XIX, siglo que se caracteriza por el surgimiento de corrientes fi losófi cas como el positivismo de Comte (1789-1857), el pragmatismo del psicólogo norteamericano James, el sociologismo de Durkheim y el Empirismo de Dewey quien aplica la corriente pragmatista y establece en 1910 las etapas o fases básicas del pensamiento científi co.Otros acontecimientos especialmente signifi cativos que podemos considerar como precedentes hacen alusión a los estudios de Weber (1795-1878), Ebbinghaus', '["educational research","history of educational research","experimental pedagogy","positivism","pragmatism","Émile Durkheim","John Dewey"]', '10.7476/9788574554938.001', NULL, 'https://doi.org/10.7476/9788574554938.001', 'https://doi.org/10.7476/9788574554938.001', NULL, NULL, NULL, 75, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-qyznn', 'qyznn', 'Prueba ilícita y regla de exclusión en materia penal: análisis teórico-práctico en derecho comparado', NULL, '["Medina Rico, Ricardo Hernán"]', 'EDITORIAL UNIVERSIDAD DEL ROSARIO', 'SciELO Books', 'books', 2017, NULL, 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'Esta obra expone lo relacionado con la prueba ilícita desde un punto de vista teórico, abordando la realidad dentro de la casuística en Derecho comparado. Así, en un primer momento busca definir la prueba dentro del proceso penal y diferenciar los conceptos de las diversas pruebas no permitidas durante este, a saber: la prueba ilegal, la prueba irregular, la prueba ilícita y la prueba no valorable –como clasificación del autor– continuación se trata el tema de los derechos de la dignidad humana y de la intimidad, como aquellos que pueden llevar a que se produzca la ilicitud de la prueba si son vulnerados. Se analizan los antecedentes históricos y el concepto de prueba ilícita desde las perspectivas estadounidense y española. A partir de este estudio de Derecho comparado, y trayendo a colación sentencias hito de América y Europa, se revisa brevemente la regla de exclusión y la teoría del árbol envenenado, así como lo relacionado con el tratamiento procesal de la prueba ilícita.', '[]', NULL, '9789587388831', 'https://books.scielo.org/id/qyznn', 'https://books.scielo.org/id/qyznn/pdf/medina-9789587388848.pdf', 'https://books.scielo.org/id/qyznn/epub/medina-9789587388848.epub', 'https://books.scielo.org/id/qyznn/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W2806719479', 'https://openalex.org/W2806719479', 'O Buen Vivir: uma oportunidade de imaginar outro mundo', NULL, '["Alberto Acosta"]', 'SciELO Network', 'Red SciELO', 'scielo-network', 2016, '2016-01-01', 'pt', 'chapter', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Alemanha.É professor da Faculdade Latino-americana de Ciências Sociais (FLACSO-Equador) e professor visitante de universidades dentro e fora do Equador.Atua como assessor de movimentos sociais e consultor internacional.É autor de numerosas publicações sobre temas relacionados ao desenvolvimento e Buen Vivir, economia, petróleo, energia, dívida externa, migração, mineração e direitos da natureza. 204 O desenvolvimento, um fantasma inalcançávelDesde meados do século XX, um fantasma percorre o mundo... Este fantasma é o desenvolvimento.E embora a maioria das pessoas, certamente, não acredite em fantasmas, pelo menos em algum momento acreditou no "desenvolvimento", se deixou influenciar pelo "desenvolvimento", perseguiu o "desenvolvimento", trabalhou pelo "desenvolvimento", viveu do "desenvolvimento"... E é muito provável que siga fazendo isso ainda hoje.Sem negar a validade da busca ancestral pela satisfação das necessidades dos seres humanos, existente há muito tempo, o desenvolvimento como proposta global se institucionalizou em 20 de janeiro de 1949.Nesta época, o presidente dos Estados Unidos, Harry Truman, no "quarto ponto" de seu discurso perante o Congresso, definiu a maior parte do mundo como sendo "áreas subdesenvolvidas".E anunciou que todas as sociedades teriam que perseguir uma só meta: "o desenvolvimento".Esta metáfora tirada da vida natural adquiriu um vigor inusitado.Tornou-se uma meta a ser alcançada por toda a humanidade.Então, no início da Guerra Fria, com o discurso do "desenvolvimento", começaram a surgir planos, programas, projetos, metodologias e manuais de desenvolvimento, bancos especializados em financiar o desenvolvimento, ajuda ao desenvolvimento, capacitação e formação para o desenvolvimento, comunicação para o desenvolvimento e muitas outras ações para alcançar o desenvolvimento.A corrida em busca deste objetivo ansiado e esquivo ainda não terminou... Em nome do "desenvolvimento", em nenhum momento os países centrais ou desenvolvidos, ou seja, nossas referências (causadores, em grande parte, do nosso subdesenvolvimento), renunciaram a diversas operações de intervenção interferência nos', '["good life","critique of development","underdevelopment","social movements","Latin America","external debt","mining"]', '10.7476/9788578794880.0006', NULL, 'https://doi.org/10.7476/9788578794880.0006', 'https://doi.org/10.7476/9788578794880.0006', NULL, NULL, NULL, 189, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W4256147093', 'https://openalex.org/W4256147093', 'Redes sociais no processo de ensino e aprendizagem: com a palavra o adolescente', NULL, '["Francineide Sales da Silva","Maria Lúcia Serafim"]', 'SciELO Network', 'Red SciELO', 'scielo-network', 2016, '2016-01-01', 'pt', 'chapter', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'INTRODUÇÃOVive-se numa sociedade de constantes transformações e a internet é responsável por grandes mudanças, no mundo atual, contribuindo positivamente em diversos setores da nossa sociedade.Sendo utilizada por vários setores da sociedade como escolas, faculdades, empresas e diversos locais, possibilitando acesso às informações e notícias do mundo em apenas um click.Em 2006, surgiram as redes sociais e o Orkut tornou-se o preferido dos internautas.Logo depois, outras redes sociais como, por exemplo, o Facebook, Blog e o Twitter.Essas Redes Sociais fazem parte do cotidiano da maioria dos usuários da internet e são utilizadas para vários fins como: obtenção do perfil de um usuário por revelar traços de comportamento e isso é aproveitado até para uma seleção de emprego, para interesses pessoais, formação de grupos de estudo, como também descoberta de novos amigos ou novas informações sobre determinado assunto. 68Além do mais, as redes sociais são inteligentes e democráticas, pois as pessoas expõem suas preferências, facilitando o trabalho das empresas, quando realizam ações voltadas para seu público-alvo, na criação de novos produtos ou quando se decide trabalhar mais em um determinado produto para atender o público de maneira satisfatória de acordo com suas preferências.As redes sociais também estão cada vez mais presentes no dia a dia de alunos e professores, no entanto, essas ferramentas ainda não são muito exploradas em sala de aula.Na maioria dos casos, as escolas não permitem o acesso a esse tipo de rede social em função do "medo" de que o aluno se interesse por assuntos que não estejam diretamente ligados aos estudos de sala de aula.Este texto é um estudo sobre "Redes sociais no processo de ensino e aprendizagem: com a palavra os adolescentes", e traz reflexões em torno do melhor aproveitamento destes espaços virtuais no processo de ensino e aprendizagem dos adolescentes, pois estes são o que se pode evidenciar como geração interativa.É fruto de estudo monográfico, sendo de natureza qualitativa exploratória, e os dados foram coletados através de um questionário semiestruturado em duas escolas, uma da rede pública Escola Estadual de Ensino Fundamental e Médio Senador Humberto Lucena e outra da rede privada Espaço Educacional Carmela Veloso no Município de Campina Grande-PB.A pesquisa ocorreu nos meses de agosto e setembro de 2010.Os respondentes do estudo foram 18 alunos da escola pública e 30 da escola particular que cursam o 1º ano do ensino médio.A faixa etária dos adolescentes está entre 14 e 17 anos de idades.O objetivo geral do estudo foi o de buscar, através da fala dos adolescentes, como está se constituindo a relação destes com as redes sociais da internet, tendo em vista as implicações desta relação', '["social networks","teaching-learning process","adolescents","internet use in schools","student voice","Facebook","Twitter"]', '10.7476/9788578793265.0004', NULL, 'https://doi.org/10.7476/9788578793265.0004', 'https://doi.org/10.7476/9788578793265.0004', NULL, NULL, NULL, 68, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W2990490403', 'https://openalex.org/W2990490403', 'Pensando a cisgeneridade como crítica decolonial', NULL, '["Viviane Vergueiro"]', 'EDUFBA eBooks', 'Red SciELO', 'scielo-network', 2016, '2016-01-01', 'pt', 'chapter', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Fiquei extremamente feliz com a oportunidade viabilizada neste Seminário Enlaçando Sexualidades,', '["cisnormativity","decolonial critique","sexuality","gender norms"]', '10.7476/9788523218669.0014', NULL, 'https://doi.org/10.7476/9788523218669.0014', 'https://doi.org/10.7476/9788523218669.0014', NULL, NULL, NULL, 48, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-m357p', 'm357p', 'Medicamentos simples para males graves: los Casos felices y auténticos de medicina de Domingo Rota como ventana abierta a las artes de curar santafereñas (Santafé, 1750-1830)', NULL, '["Ortega Martínez, María Liliana"]', 'EDITORIAL UNIVERSIDAD DEL ROSARIO', 'SciELO Books', 'books', 2016, NULL, 'es', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', NULL, '“Con todas las cosas creó Dios la medicina, simple y específica; y a la naturaleza, admirable en lo productiva y conservativa, y vio que todo era excelente, bueno”, de esta manera comienzan los Casos felices y auténticos de medicina del relojero, platero y médico Domingo Rota; libro que dio vida a esta investigación. Este ejercicio microhistórico busca esclarecer algunos aspectos claves de la medicina neogranadina de finales del siglo XVIII en Santafé y sus alrededores, a través de la comprensión y estudio de los casos médicos presentados por Domingo Rota en su libro. El texto explora eventos de la vida de este singular personaje, su proceso de aprendizaje del saber médico, el trato que este mantenía con otros practicantes, los contenidos de su libro y la relación que todos estos aspectos establecen con el universo en el que Domingo llevó a cabo su práctica.', '[]', NULL, '9789587387254', 'https://books.scielo.org/id/m357p', 'https://books.scielo.org/id/m357p/pdf/ortega-9789587387261.pdf', 'https://books.scielo.org/id/m357p/epub/ortega-9789587387261.epub', 'https://books.scielo.org/id/m357p/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W2194538640', 'https://openalex.org/W2194538640', 'Desenvolvimentismo a construção do conceito', NULL, '["Pedro Cézar Dutra Fonseca"]', 'Editora da UFRGS eBooks', 'Red SciELO', 'scielo-network', 2015, '2015-01-01', 'pt', 'chapter', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Fonseca 1. IntroduçãoO que é desenvolvimentismo?A resposta remete à conceituação de um termo de largo uso entre os economistas e já incorporado pela mídia, mas que carece de defi nição mais precisa.Como outros termos teóricos ou categorias utilizados pelos economistas (como "desenvolvimento", "bem--estar", "equilíbrio" e "valor"),', '["developmentalism","concept formation","economic terminology","development","welfare","economic equilibrium","economic value"]', '10.7476/9788538603825.0002', NULL, 'https://doi.org/10.7476/9788538603825.0002', 'https://doi.org/10.7476/9788538603825.0002', NULL, NULL, NULL, 59, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-fjzjm', 'fjzjm', 'Educación legal clínica y litigio estratégico en Iberoamérica', NULL, '["Beatriz Socorro Londoño Toro"]', 'Editorial Universidad del Rosario eBooks', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra es resultado de investigación sobre dos conceptos de enorme importancia para la educación jurídica en Iberoamérica: la educación legal clínica como modelo pedagógico en construcción y el litigio estratégico como herramienta de incidencia social y política. Se considera que el proceso de construcción de las clínicas en la región es un hito en la educación jurídica iberoamericana y existen evidencias que permiten afirmarlo, ya que se trata de historias paralelas que se fortalecieron por los intercambios de aprendizajes y experiencias a través de las redes. De igual manera se desarrolla el concepto de litigio estratégico o estructural y se examina la forma como inciden en dicha propuesta las alianzas estratégicas. Se pasa luego a una profundización sobre la agenda de las clínicas y los temas prioritarios de Derechos Humanos en Iberoamérica. Examen que se realiza a partir de casos reales que se han trabajado las clínicas. Se concluye en la necesidad del surgimiento de nuevas clínicas y de más proyectos de investigación.', '["clinical legal education","strategic litigation","structural litigation","Ibero-America","legal education","strategic alliances","human rights"]', '10.7476/9789587386240', NULL, 'https://books.scielo.org/id/fjzjm', 'https://books.scielo.org/id/fjzjm/pdf/londono-9789587386240.pdf', NULL, 'https://books.scielo.org/id/fjzjm/cover/cover_thumbnail.jpeg', NULL, 20, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-49tbx', '49tbx', 'Estrategias de enseñanza aprendizaje en ambientes musicales. Enfoque para niños, niñas y adolescentes con discapacidad víctimas del conflicto armado colombiano', NULL, '["Larrota Veloza, Óscar Javier","Castro Alzate, Elvis Siprian","Aguía Rojas, Karen","Navas Solano, María Carolina","Ruiz Acuña, Mónica María"]', 'EDITORIAL UNIVERSIDAD DEL ROSARIO', 'SciELO Books', 'books', 2015, NULL, 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'Estrategias de enseñanza aprendizaje en ambientes musicales. Enfoque para niños, niñas y adolescentes con discapacidad víctimas del conflicto armado colombiano, es uno de los resultados destacables de la alianza de cinco años, celebrada entre la Universidad Colegio Mayor del Rosario y la Fundación Nacional Batuta, para profundizar y dinamizar el trabajo en el área de terapia ocupacional en beneficio de los procesos pedagógicos y musicales de los niños y niñas con discapacidad pertenecientes al Programa Música para la Reconciliación. Esta publicación refleja la interlocución de saberes entre la música y la terapia ocupacional y presenta algunas estrategias que favorecen los procesos de enseñanza/ aprendizaje de la población con discapacidad en el marco del campo de acción de la Fundación. Así mismo, presenta elementos esenciales para la motivación de los equipos interdisciplinarios que trabajan, día a día, en las clases de música para facilitar la participación activa en la formación musical de las personas en situación de discapacidad. Este libro es una herramienta útil para los trabajadores sociales, los terapeutas ocupacionales, los profesores de música, las personas vinculadas a procesos formativos o participativos mediante los cuales se atienden personas en condición de discapacidad y para todos aquellos que creen –como nosotros– que la música es un vehículo fundamental para favorecer el desarrollo del ser humano.', '[]', '10.7476/9789587386950', '9789587386943', 'https://books.scielo.org/id/49tbx', NULL, NULL, 'https://books.scielo.org/id/49tbx/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-vvp5w', 'vvp5w', 'Anulabilidad de las cláusulas abusivas', NULL, '["Correa Valenzuela, Gustavo Andrés"]', 'EDITORIAL UNIVERSIDAD DEL ROSARIO', 'SciELO Books', 'books', 2015, NULL, 'es', 'book', 'engineering-tech', 'Ingeniería y Tecnología', NULL, 'Esta obra presenta el problema del desconocimiento de la naturaleza jurídica del fenómeno denominado “cláusulas abusivas”, partiendo de la existencia de la gran diversidad de planteamientos y tratamientos jurídicos dados a dicho fenómeno a nivel internacional, con principal énfasis en el ordenamiento jurídico colombiano, donde se encuentran distintas concepciones y consecuencias para el mismo fenómeno. Ante dicha situación se pretende determinar cuál es la naturaleza jurídica de las cláusulas abusivas, los elementos y requisitos para que se configure dicho fenómeno jurídico para poder determinar cuál es la consecuencia jurídica que debe aplicarse al mismo, procurando una simetría entre una y otra, así como un entendimiento a mayor profundidad del fenómeno que tanta importancia ha cobrado a nivel internacional en los últimos años debido a la masificación y estandarización de la contratación en los distintos sectores económicos y comerciales, proponiendo que la consecuencia adecuada para una cláusula que constituya un abuso debe ser la anulabilidad o nulidad relativa de la misma. El planteamiento que se propone, enfocado en el análisis del contrato de seguros y la posibilidad de abuso de posición dominante contractual en la predisposición de las cláusulas a regir en dicho contrato, no obsta para que pueda ser aplicado a los demás contratos civiles y mercantiles, toda vez que al ser el mismo fenómeno jurídico del que trata la obra, la consecuencia de este ha de ser igual tratándose del mismo contrato en el que una de las partes se encuentre en la capacidad de determinar unilateralmente las condiciones que regirán la ejecución del contrato.', '[]', '10.7476/9789587386301', '9789587386295', 'https://books.scielo.org/id/vvp5w', 'https://books.scielo.org/id/vvp5w/pdf/correa-9789587386301.pdf', 'https://books.scielo.org/id/vvp5w/epub/correa-9789587386301.epub', 'https://books.scielo.org/id/vvp5w/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-zd6bp', 'zd6bp', 'Resultados maternos y fetales de la actividad física durante el embarazo', NULL, '["Ramírez Vélez, Robinson","Correa Bautista, Jorge Enrique"]', 'EDITORIAL UNIVERSIDAD DEL ROSARIO', 'SciELO Books', 'books', 2015, NULL, 'es', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', NULL, 'Esta obra reúne información relevante y novedosa para el estudio de la actividad física durante la gestación y brinda los lineamientos necesarios para que los profesionales de las ciencias de la salud y los profesionales de las ciencias de la educación física y del deporte puedan promover la actividad física y prescribir y monitorear el ejercicio durante esta etapa del ciclo vital de la mujer.  Los autores logran dar respuesta a un vacío conceptual y metodológico sobre la forma de promover la actividad física y el ejercicio, ya que durante muchos años se pensó que eran contraindicados durante la gestación.', '[]', '10.7476/9789587386059', '9789587386042', 'https://books.scielo.org/id/zd6bp', NULL, NULL, 'https://books.scielo.org/id/zd6bp/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-r7md6', 'r7md6', 'El amparo de tierras: la acción, el proceso y el juez de restitución', NULL, '["Quinche Ramírez, Manuel Fernando","Peña Huertas, Rocío del Pilar","Parada Hernández, María Mónica","Ruiz González, Luis Enrique","Álvarez Morales, Ricardo"]', 'EDITORIAL UNIVERSIDAD DEL ROSARIO', 'SciELO Books', 'books', 2015, NULL, 'es', 'book', 'engineering-tech', 'Ingeniería y Tecnología', NULL, 'Esta obra es resultado de una revisión de los fallos de restitución proferidos desde el último trimestre del 2012 hasta las últimas que fueron publicadas del año 2014, que se hicieron públicos a través de los sitios de internet de la Unidad de Restitución de Tierras y del Consejo Superior de la Judicatura. Todos los fallos fueron organizados y sistematizados en una matriz que permitiera identificar los hechos principales expuestos en cada fallo, los asuntos que serían desarrollados en el mismo y los problemas jurídicos que abordó cada uno. El libro se desarrolla de la siguiente manera: en el primer capítulo se enmarca la tesis que se defiende, es decir, que los jueces de restitución son jueces constitucionales y pueden de acuerdo con López construir precedente horizontal. En el capítulo 2 se abordarán las decisiones judiciales sobre acumulación de procesos a la restitución de tierras. Luego, se tratará el tema de la titulación conyugal en el marco de los fallos de restitución. En el  capítulo 4 nos referimos a las decisiones relevantes sobre la aplicación del enfoque diferencial en el proceso de restitución. Posteriormente se analizará la cuestión de la buena fe exenta de culpa y los opositores en las sentencias de restitución.  En seguida, en el capítulo 6 se abordarán los fallos de restitución relevantes sobre el tema de la adjudicación de baldíos a través del proceso de restitución. Muy relacionado con este tema, en el siguiente capítulo se trata la relación de la restitución de tierras con la Unidad Agrícola Familiar (UAF) como figura particular de la legislación agraria. A continuación, en el capítulo 8 se analizarán las decisiones judiciales más relevantes sobre la restitución en Zonas de Reserva Forestal (ZRF). Finalmente el capítulo 9 se encargará de analizar los procesos de restitución en las zonas en las que hay labores de exploración y explotación de recursos minero-energéticos.', '[]', '10.7476/9789587386752', '9789587386745', 'https://books.scielo.org/id/r7md6', NULL, NULL, 'https://books.scielo.org/id/r7md6/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-r3wvb', 'r3wvb', 'Justicia para los vasallos de su majestad. Administración de justicia en la villa de San Gil, siglo XVIII', NULL, '["Velasco Pedraza, Julián Andrei"]', 'EDITORIAL UNIVERSIDAD DEL ROSARIO', 'SciELO Books', 'books', 2015, NULL, 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'Para la monarquía hispánica gobernar era hacer justicia. Bajo este fundamento, la corona de Castilla construyó todo un complejo aparato de tribunales en sus dominios americanos. Esta obra analiza una parte de ese gobierno por medio de la administración de justicia de la villa de San Gil en el siglo XVIII. Desde una perspectiva histórico-jurídica, fundamentada en nuevas visiones sobre el derecho y las instituciones, se estudia cómo en un ámbito local funcionaban y se adaptaban criterios culturales y principios jurídicos generales de la tradición jurídica de Occidente. Mediante el estudio de las condiciones locales, las jurisdicciones y jueces que las ejercían, así como de otros elementos del gobierno, se traza un panorama de la lógica de funcionamiento de una parte de la monarquía. Un tema poco estudiado para el virreinato de Santa Fe y que puede ayudar al mejor entendimiento de las lógicas político-administrativas del siglo XVIII, además de comprender, de forma menos anacrónica, las fuentes judiciales que eran producto de una cultura jurídica distinta a la de nuestros días.', '[]', '10.7476/9789587386547', '9789587386530', 'https://books.scielo.org/id/r3wvb', NULL, NULL, 'https://books.scielo.org/id/r3wvb/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-w7b8v', 'w7b8v', 'Reflexiones en torno a derechos humanos y grupos vulnerables', NULL, '[]', 'EDITORIAL UNIVERSIDAD DEL ROSARIO', 'SciELO Books', 'books', 2015, NULL, 'es', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', NULL, 'Esta obra colectiva contiene reflexiones académicas, y no simples compilaciones normativas, que presentan diversos puntos de análisis sobre los retos para la protección de los derechos de las minorías y se plantean las problemáticas de varios de estos grupos. Así mismo, la reflexión propuesta en la introducción presenta argumentos que conectan las generalidades de estos grupos pese a los particularismos sociales o jurídicos que se debe exigir para que tengan un adecuado reconocimiento de sus derechos.', '[]', NULL, '9789587386851', 'https://books.scielo.org/id/w7b8v', NULL, NULL, 'https://books.scielo.org/id/w7b8v/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-8nq45', '8nq45', 'Reforma radical en el estado de Santander, 1850-1885', NULL, '["Zapata Giraldo, Juan Gonzalo"]', 'EDITORIAL UNIVERSIDAD DEL ROSARIO', 'SciELO Books', 'books', 2015, NULL, 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'A lo largo del siglo xix el país se vio obligado a definirse en favor o en contra de tres modelos políticos que tenían grandes diferencias entre sí. Por supuesto, uno de estos era el radical, que finalmente fue derrotado por uno mucho más fuerte, que logró imponerse durante un periodo muy largo. Sin embargo, durante los años radicales se vivieron una expansión económica y un progreso social importantes que poco se han valorado, pues a lo largo de casi treinta años del siglo xix el discurso y la política nacional yregional se movieron alrededor de las reformas radicales. Así, este extenso periodo de Gobierno conocido como la hegemonía radical permite mostrar en este libro cuáles fueron las políticas abanderadas por este grupo político y cuál fue su impacto tanto en el Gobierno Federal como en las regiones, pues su influencia en algunas fue permanente, pese al interés de los conservadores por anularlas. Un ejemplo de esta hegemonía es Santander, un estado que construirían los radicales, parte de una federación, laico, con vocación de estimular la actividad económica y donde s reconocía el papel que deberían desempeñar los empresarios y los comerciantes para lograr el anhelado progreso económico. Este libro permitirá conocer en detalle la puesta en marcha de las reformas en algunos sectores, analizar sus fuentes de financiamiento y los criterios para canalizar los recursos a algunos sectores del gasto público que consideraron prioritario y entender las novedosas herramientas administrativas utilizadas por los radicales, y con ello emitir un juicio final sobre sus políticas.', '[]', '10.7476/9789587387049', '9789587387032', 'https://books.scielo.org/id/8nq45', NULL, NULL, 'https://books.scielo.org/id/8nq45/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W2035639136', 'https://openalex.org/W2035639136', 'El análisis factorial exploratorio de los ítems: una guía práctica, revisada y actualizada', NULL, '["Susana Lloret-Segura","Adoración Ferreres Traver","Ana Hernández","Inés Tomás-Marco"]', 'Anales de Psicología', 'Red SciELO', 'scielo-network', 2014, '2014-09-12', 'es', 'article', 'social-sciences', 'Ciencias Sociales y Educación', 'Decision Sciences', 'Exploratory Factor analysis is one of the techniques used in the development, validation and adaptation of psychological measurement instruments. Its use spread during the 1960s and has been growing exponentially thanks to the advancement of information technology. The criteria used, of course, have also evolved. But the applied researchers, who use this technique as a routine, remain often ignorant of all this. In the last few decades numerous studies have denounced this situation. There is an urgent need to update the classic criteria. The incorporation of the most suitable criteria will improve the quality of our research. In this work we review the classic criteria and, depending on the case, we also propose current criteria to replace or complement the former. Our objective is to offer the interested applied researcher updated guidance on how to perform an Exploratory Item Factor Analysis, according to the “post-Little Jiffy” psychometrics. This review and the guide with the corresponding recommendations have been articulated in four large blocks: 1) the data type and the matrix of association, 2) the method of factor estimation, 3) the number of factors to be retained, and 4) the method of rotation and allocation of items. An abridged version of the complete guide is provided at the end of the article.', '["exploratory factor analysis","rotation method","item allocation","association matrix","psychometrics"]', '10.6018/analesps.30.3.199361', NULL, 'https://doi.org/10.6018/analesps.30.3.199361', 'https://revistas.um.es/analesps/article/download/analesps.30.3.199361/165441', NULL, NULL, NULL, 2190, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W2033146070', 'https://openalex.org/W2033146070', 'Sisvar: a Guide for its Bootstrap procedures in multiple comparisons', NULL, '["Daniel Furtado Ferreira"]', 'Ciência e Agrotecnologia', 'SciELO Brasil', 'scielo-br', 2014, '2014-04-01', 'en', 'article', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Sisvar is a statistical analysis system with a large usage by the scientific community to produce statistical analyses and to produce scientific results and conclusions. The large use of the statistical procedures of Sisvar by the scientific community is due to it being accurate, precise, simple and robust. With many options of analysis, Sisvar has a not so largely used analysis that is the multiple comparison procedures using bootstrap approaches. This paper aims to review this subject and to show some advantages of using Sisvar to perform such analysis to compare treatments means. Tests like Dunnett, Tukey, Student-Newman-Keuls and Scott-Knott are performed alternatively by bootstrap methods and show greater power and better controls of experimentwise type I error rates under non-normal, asymmetric, platykurtic or leptokurtic distributions.', '["bootstrapping","multiple comparisons","Dunnett test","Tukey test","statistical software","non-normal distributions"]', '10.1590/s1413-70542014000200001', NULL, 'https://doi.org/10.1590/s1413-70542014000200001', 'https://www.scielo.br/j/cagro/a/yyWQQVwqNcH6kzf9qT9Jdhv/?lang=en&format=pdf', NULL, NULL, NULL, 2003, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-mw58j', 'mw58j', 'Vetores da doença de Chagas no Brasil', NULL, '["Cléber Galvão"]', 'SciELO Network', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Os triatomíneos são insetos hematófagos de grande importância médica, pois são os responsáveis pela transmissão do Trypanosoma cruzi, o agente etiológico da doença de Chagas. Durante mais de um século, desde a descrição da primeira espécie em 1773, os triatomíneos foram estudados de um ponto de vista puramente entomológico. Porém, a partir de 1909, quando Carlos Chagas descobriu que eram os vetores de uma nova tripanossomíase, que mais tarde levaria o seu nome, adquiriram um interesse médico sanitário muito grande despertando a curiosidade de vários pesquisadores que passaram a estudá-los sob os mais variados aspectos. “Vetores da doença de Chagas no Brasil” é uma obra composta por 13 capítulos, com linguagem acessível a públicos com diferentes níveis de formação, voltada principalmente para equipes que atuam em vigilância entomológica, professores e alunos de graduação e pós-graduação. A obra aborda e atualiza diversos aspectos relacionados aos vetores como: taxonomia, biologia, comportamento, mecanismos de transmissão e relação com os mamíferos reservatórios do Trypanosoma cruzi', '["Chagas disease","Chagas disease vectors","Trypanosoma cruzi","disease vectors","vector biology","vector behavior","transmission mechanism"]', '10.7476/9788598203096', NULL, 'https://books.scielo.org/id/mw58j', 'https://books.scielo.org/id/mw58j/pdf/galvao-9788598203096.pdf', NULL, 'https://books.scielo.org/id/mw58j/cover/cover_thumbnail.jpeg', NULL, 128, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W2949399438', 'https://openalex.org/W2949399438', 'A tecnologia social e seus desafios', NULL, '["Renato Dagnino"]', 'SciELO Network', 'Red SciELO', 'scielo-network', 2014, '2014-01-01', 'pt', 'chapter', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Documento científico en Acceso Abierto (Social Sciences) publicado en SciELO Network.', '["social technology","social innovation"]', '10.7476/9788578793272.0004', NULL, 'https://doi.org/10.7476/9788578793272.0004', 'https://doi.org/10.7476/9788578793272.0004', NULL, NULL, NULL, 120, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-yn4vh', 'yn4vh', 'Los límites de la estratificación: en busca de alternativas', NULL, '["Carlos E. Sepúlveda","Denis López Camacho","Juan Miguel Gallego Acevedo"]', 'Editorial Universidad del Rosario eBooks', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra presenta un diagnóstico sobre las deficiencias técnicas del sistema actual de estratificación socioeconómica en la ciudad de Bogotá. Propone como um instrumento más eficiente para la clasificación socioeconómica la utilización de información catastral, em particular aquella relacionada con el avalúo catastral. Presenta una discusión sobre las consecuencias que trae esta nueva alternativa de clasificación sobre las tarifas y subsidios a los servicios públicos domiciliarios y propone posibles esquemas en caso de adoptarse uma clasificación ocioeconómica a través de la información catastral. El diagnóstico sobre la estratificación vigente y el desarrollo de alternativas de definición de subsidios cruzados en servicios públicos domiciliarios (spd), cumplen con un vacío en la literatura colombiana sobre métodos alternativos al sistema actual de estratificación, el cuál ha sido diagnosticado por expertos, académicos y hacedores de política como ineficiente, con riesgos sobre la estabilidad fiscal del sistema de tarifas y com consecuencias indirectas sobre los hogares y la localización urbana de los mismos. De igual forma abre uma agenda de debate e investigación sobre el uso de la información catastral en Bogotá y su aplicación a nivel nacional para focalizar mejor y facilitar el diseño de políticas sociales hacia los hogares, como los subsidios en spd, así como para el diseño de políticas de territorio al interior de las ciudades.', '["socioeconomic stratification","cadastral valuation","household classification","public utility tariffs","cross-subsidization","fiscal stability","urban social policy"]', '10.7476/9789587385373', NULL, 'https://books.scielo.org/id/yn4vh', 'https://books.scielo.org/id/yn4vh/pdf/sepulveda-9789587385373.pdf', NULL, 'https://books.scielo.org/id/yn4vh/cover/cover_thumbnail.jpeg', NULL, 15, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W2056864356', 'https://openalex.org/W2056864356', 'Un sistema de clasificación de los diseños de investigación en psicología', NULL, '["Manuel Ato","Juan José López García","Ana Benavente"]', 'Anales de Psicología', 'Red SciELO', 'scielo-network', 2013, '2013-09-24', 'es', 'article', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'In this work we devise a conceptual framework and develop some basic principles to promove a classification system for the most usual research designs in psychology based on three strategies (manipulative, associative and descriptive) from which emerge different types of studies, three for manipulative strategy (experimental, quasi-experimental and single-case), three for associative strategy (comparative, predictive and explanatory) and two for descriptive strategy (observational and selective).', '["manipulation techniques","associative strategies","experimental design","quasi-experimental design","single-case experimental design","comparative design","predictive design"]', '10.6018/analesps.29.3.178511', NULL, 'https://doi.org/10.6018/analesps.29.3.178511', 'https://revistas.um.es/analesps/article/download/analesps.29.3.178511/152221', NULL, NULL, NULL, 3573, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-468vp', '468vp', 'Injustiça ambiental e saúde no Brasil: o Mapa de Conflitos', NULL, '["Marcelo Firpo Porto","Tania Pacheco","Jean Pierre Leroy"]', 'Editora FIOCRUZ eBooks', 'SciELO Books', 'books', 2013, '2013-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Apresentação O Mapa dos Conflitos Ambientais no Estado do Rio de JaneiroO debate sobre problemas ambientais sob a ótica das desigualdades sociais, políticas, econômicas e culturais e, portanto, das injustiças presentes no modelo hegemônico de sociedade já era fundamental e estruturante em entidades como a Fase, mais especificamente no projeto BSD.Com a criação da rede, pode-se dizer que o projeto acumulou mais força política, aglutinando diferentes sujeitos e impondo novos desafios à sua prática.Antes da criação da RBJA, o debate sobre os conflitos ambientais no país já tinha sido realizado por iniciativas de várias entidades e grupos universitários, como o Instituto Brasileiro de Análises Sociais e Econômicas (Ibase), a Central Única dos Trabalhadores do Rio de Janeiro (CUT-RJ), pesquisadores do Instituto de Pesquisa e Planejamento Urbano e Regional (Ippur) e do Museu Nacional da Universidade Federal do Rio de Janeiro (UFRJ), da UFF, além de outros grupos acadêmicos ligados às ciências sociais e à saúde coletiva, como a Fiocruz (Herculano, Porto & Freitas, 2000; Ibase/CUT-RJ/Ippur/UFRJ, 2000).Os problemas ambientais já eram tema obrigatório das discussões inseridas no projeto BDS/Fase, e, com a criação da rede, novos parceiros fomentaram a ideia de se construir um Mapa de Conflitos Ambientais do Rio de Janeiro (Acselrad, Herculano & Pádua, 2004).Com o vigor da recém-criada RBJA, em novembro de 2002 o BSD/Fase promoveu uma oficina para se pensar numa forma de viabilizar essa estratégia de luta em torno dos conflitos e movimentos por justiça ambiental, partindo do levantamento do "perfil do conhecimento disponível, das pesquisas em andamento e dos esforços dos pesquisadores" que se dedicavam, "no âmbito das mais diversas instituições universitárias e de pesquisa, ao estudo de conflitos ambientais no Estado do Rio de Janeiro", conforme consta da apresentação do CD-ROM "Mapa dos Conflitos Ambientais no Estado do Rio de Janeiro 2002-2005".Como consequência da oficina, em janeiro de 2004 o projeto BSD/Fase e o laboratório Estado, Trabalho, Território e Natureza (Ettern/Ippur/UFJR) lançavam o Mapa dos Conflitos Ambientais do Estado do Rio de Janeiro 1992-2002.Com o apoio da Secretaria de Estado de Meio Ambiente e Desenvolvimento Urbano do Rio de Janeiro e com recursos provenientes de um Termo de Ajuste de Conduta da Petrobras, após o desastre ambiental ocorrido na baía de Guanabara em 2000, o mapa foi produzido em CD-ROM no qual se compilaram 251 casos cujos registros foram colhidos de documentos da Fundação Estadual de Engenharia do Meio Ambiente (Feema) e dos ministérios públicos estadual e federal.Deles, 183 diziam respeito a atividades 21 industriais; 48, à ausência de saneamento; dez conjugavam essas duas questões; e outros dez envolviam temas diversos.Dois anos mais tarde, em 2006, os mesmos parceiros lançaram um novo Mapa dos Conflitos Ambientais no Estado do Rio de Janeiro, também em CD-ROM, totalizando, assim, 480 conflitos ocorridos entre 2002 e 2005, aos quais foram ainda acrescentados estudos analíticos dos casos.Às fontes iniciais -Feema e os ministérios públicos estadual e federal -se somariam também casos registrados pelo Departamento de Recursos Minerais do Estado do Rio de Janeiro, pela Secretaria Municipal de Meio Ambiente do Rio de Janeiro e pela Secretaria de Urbanismo e Meio Ambiente de Mesquita.2Os conflitos, selecionados ao longo de trinta meses, relativos ao período de 2002 a 2005, foram georreferenciados em 68 municípios e sistematizados em 18 classificações específicas: mineração; disposição não licenciada de resíduos industriais; depósito licenciado de resíduos industriais; armazenamento temporário de resíduos industriais; poluição atmosférica; poluição de corpo hídrico; poluição do solo; poluição sonora; gasodutos, oleodutos, estações rádio-base e linhas de transmissão; vazadouros de lixo; lançamento de esgoto em corpo hídrico; acesso à água potável; apropriação de corpo hídrico; deslocamento compulsório de assentamento humano; ocupações irregulares; moradia de risco; comprometimento da pesca; e futuros empreendimentos (Acselrad, 2004).Ainda de acordo com as informações apresentadas no CD-ROM, Os casos foram organizados por município de ocorrência do evento denunciado e classificados em grandes categorias, segundo o tipo de problema ambiental a que estiveram associados, a saber: conflitos associados a atividades industriais -poluição industrial da água, do ar e do solo, mineração irregular e disposição irregular de resíduos industriais; conflitos associados à falta de saneamento, localização e operação de lixões e aterros sanitários; conflitos associados simultaneamente a atividades industriais e à falta de saneamento; e outros. O Mapa de Conflitos Causados por Racismo Ambiental no BrasilEnquanto se produzia o segundo CD-ROM sobre os conflitos do estado do Rio de Janeiro, o debate acerca da necessidade de criação de instrumentos de registros e publicização dos casos de injustiça ambiental no país começaram a se intensificar dentro da própria RBJA, presente nas discussões coletivas nos A Estrutura do LivroComo este livro tem como tema o Mapa de Conflitos, mas não trata apenas dele, houve uma preocupação inicial em se explicar a forma como se chegou ao mapa.Essa explicação está no capítulo 1, em que se apresenta a metodologia utilizada e se resumem os casos presentes no mapa.Já a 29 partir do capítulo seguinte, o livro toma outro caminho: os resultados e as conclusões que podemos colher do mapa passam a ser objeto de diferentes análises específicas, servindo de base para questionamentos, observações críticas e sugestões sobre alternativas de enfrentamento das causas geradoras dos conflitos em pauta.Em última instância, o que se encontra em jogo é a crítica do modelo hegemônico de desenvolvimento que impõe interesses de curto prazo dos grupos mais poderosos às populações atingidas.No capítulo 2, adentra-se num um terreno pouco discutido nos meios acadêmicos, mas que o Mapa de Conflitos nos desafia a encarar, dado o caráter de insofismável prevalência que assume no conjunto da pesquisa: o racismo ambiental.Nele se analisa a forma como o capital utiliza o racismo e o preconceito para expulsar povos indígenas, quilombolas e comunidade tradicionais de seus espaços originários, de suas culturas e tradições, no campo, ao passo que, nas cidades, pobreza e negritude predominam nos embates com a especulação imobiliária e as indústrias poluentes.Grande parte dessas personagens é retomada no capítulo 3, em que os conflitos são objeto de análise sob um enfoque complementar especializado: o da territorialidade.Trabalhadores rurais também são mencionados, mas o protagonismo do estudo recai novamente sobre os povos originários e as comunidades tradicionais, com seus embates pelo direito a um território que, para eles, tem um significado que até mesmo os operadores do sistema de Justiça enfrentam dificuldade de compreender.No capítulo 4, discutem-se as injustiças ambientais nos espaços das cidades, campos e florestas.Trata-se de uma questão de grande complexidade, já que tais espaços são influenciados por inúmeras dinâmicas que tanto os diferenciam como os interconectam.Por exemplo, no campo destacamos a expansão do agronegócio, dos monocultivos e o uso intensivo dos agrotóxicos, mas isso também influencia a migração campo-cidade e o conjunto da população que consome alimentos contaminados.Nas cidades, a perversa combinação das desigualdades socioespaciais com empreendimentos, como complexos portuários e indústrias perigosas, intensifica a formação das zonas de sacrifício.Porém, tais empreendimentos também avançam sobre os espaços onde vivem populações indígenas, quilombolas e camponesas.Abordam-se, nos capítulos 5 e 6, duas forças motrizes de grande relevância para a geração de conflitos ambientais no contexto brasileiro: a primeira trata da mineração e da siderurgia, e a segunda da produção de energia.A mineração é uma atividade intensiva em recursos naturais, especialmente o solo e a água.Isso coloca em risco os ecossistemas e a existência de outras Referências ACSELRAD, H. (Org.).', '["environmental injustice","environmental conflicts","Rio de Janeiro","social movements","health and environment","social inequality","collective health"]', '10.7476/9788575415764', NULL, 'https://books.scielo.org/id/468vp', 'https://books.scielo.org/id/468vp/pdf/porto-9788575415764.pdf', NULL, 'https://books.scielo.org/id/468vp/cover/cover_thumbnail.jpeg', NULL, 69, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-4jfjj', '4jfjj', 'Comunistas brasileiros: cultura política e produção cultural', NULL, '["Napolitano, Marcos","Czajka, Rodrigo","Motta, Rodrigo Patto Sá"]', 'EDITORA UFMG', 'SciELO Books', 'books', 2013, NULL, 'pt', 'book', 'humanities', 'Humanidades y Artes', NULL, 'Esta coletânea representa uma proposta inovadora, ao reunir textos que abordam o tema do comunismo por um viés ainda pouco explorado na literatura acadêmica, enfocando-o como cultura política e como agência produtora de padrões de comportamento e de crenças. A motivação é oferecer melhor entendimento dos elementos constituintes da cultura comunista, cujos valores e ideias circularam para além dos espaços tradicionais da esquerda, fornecendo temas e argumentos para os agentes produtores de cultura, assim como inspirando determinadas políticas culturais. Pretende-se, desse modo, avaliar a força de atração e a capacidade de reprodução dos valores e padrões comunistas, decisiva para a compreensão da modernidade cultural e política brasileira.', '[]', '10.7476/9786558580836', '9788570419989', 'https://books.scielo.org/id/4jfjj', NULL, NULL, 'https://books.scielo.org/id/4jfjj/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-sn23w', 'sn23w', 'Peixes do baixo rio Iguaçu', NULL, '["Gilmar Baumgartner","Carla Simone Pavanelli","Dirceu Baumgartner","Alessandro Gasparetto Bifi","Tiago Debona","Vitor André Frana"]', 'SciELO Network', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'O rio Iguaçu nasce na confluência dos rios Atuba e Irai, e desemboca no rio Paraná, em Foz do Iguaçu. A ictiofauna deste rio, desde os primeiros trabalhos realizados, sempre foi considerada pobre e de pequeno porte, entretanto, apresenta um elevado grau de endemismo favorecido pelo surgimento das Cataratas do Iguaçu, que exerceram um papel fundamental neste processo. Esta obra busca uma fonte aglutinadora, mas sintetizada, sistematizada, especializada e atualizada das informações publicadas, até o momento, sobre a ictiofauna do baixo rio Iguaçu, fornecendo chaves de identificação, caracterizações morfológicas, fotos, dados sobre a biologia e distribuição geográfica das espécies registradas na região, além de um glossário com termos técnicos.', '["ichthyofauna","Iguazu Falls","endemism","identification key","fish morphology","fish biology","geographic distribution"]', '10.7476/9788576285861', NULL, 'https://books.scielo.org/id/sn23w', 'https://books.scielo.org/id/sn23w/pdf/baumgartner-9788576285861.pdf', NULL, 'https://books.scielo.org/id/sn23w/cover/cover_thumbnail.jpeg', NULL, 116, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W4241354135', 'https://openalex.org/W4241354135', 'Semiologia nutricional', NULL, '["Lílian Ramos Sampaio","Maria da Conceição Monteiro da Silva","Tatiane Melo de Oliveira","Venusca Rocha Leite"]', 'EDUFBA eBooks', 'Red SciELO', 'scielo-network', 2012, '2012-01-01', 'pt', 'chapter', 'medical-health', 'Ciencias Médicas y de la Salud', 'Nursing', 'O termo semiologia, criado a partir do grego sèmeion (sinal) e logos (estudo, ciência), designa a ciência dos sinais, isto é, a ciência que estuda a organização dos sistemas significantes.Na área da saúde, a semiologia compreende o estudo dos sinais e sintomas do indivíduo, no qual os sinais representam as manifestações clínicas de uma doença observadas pelo examinador por meio da inspeção, palpação ou ausculta.Os sintomas são sensações subjetivas, sentidas pelo indivíduo e não visualizada pelo examinador.E, para avaliação dessas alterações e/ou manifestações semiológicas, no que se refere aos problemas nutricionais, o nutricionista dispõe da anamnese nutricional para a identificação dos sintomas clínicos nutricionais e do exame físico na avaliação dos sinais clínicos nutricionais.O exame clínico nutricional consiste em avaliar as alterações orgânicas expressas nos tecidos externos', '["clinical signs","clinical symptoms","nutritional history","physical examination","nutritional assessment"]', '10.7476/9788523218744.0004', NULL, 'https://doi.org/10.7476/9788523218744.0004', 'https://doi.org/10.7476/9788523218744.0004', NULL, NULL, NULL, 44, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W1747388711', 'https://openalex.org/W1747388711', 'Sisvar: a computer statistical analysis system', NULL, '["Daniel Furtado Ferreira"]', 'Ciência e Agrotecnologia', 'SciELO Brasil', 'scielo-br', 2011, '2011-12-01', 'en', 'article', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Mathematics', 'Sisvar is a statistical analysis system, first released in 1996 although its development began in 1994. The first version was done in the programming language Pascal and compiled with Borland Turbo Pascal 3. Sisvar was developed to achieve some specific goals. The first objective was to obtain software that could be used directly on the statistical experimental course of the Department of Exact Science at the Federal University of Lavras. The second objective was to initiate the development of a genuinely Brazilian free software program that met the demands and peculiarities of research conducted in the country. The third goal was to present statistical analysis software for the Brazilian scientific community that would allow research results to be analyzed efficiently and reliably. All of the initial goals were achieved. Sisvar gained acceptance by the scientific community because it provides reliable, accurate, precise, simple and robust results, and allows users a greater degree of interactivity.', '["statistical software","free software","statistical software development","agricultural experiments","statistics education","Brazilian scientific community"]', '10.1590/s1413-70542011000600001', NULL, 'https://doi.org/10.1590/s1413-70542011000600001', 'https://www.scielo.br/j/cagro/a/yjKLJXN9KysfmX6rvL93TSh/?lang=en&format=pdf', NULL, NULL, NULL, 7291, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W2952406843', 'https://openalex.org/W2952406843', 'A abordagem etnográfica na investigação científica', NULL, '["Carmem Lúcia Guimarães de Mattos"]', 'SciELO Network', 'Red SciELO', 'scielo-network', 2011, '2011-01-01', 'pt', 'chapter', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A etnografia como uma abordagem de investigação científica é explorada nesse texto para de monstrar como esta abordagem de pesquisa traz algumas contribuições importantes ao campo das pesquisas qualitativas, especialmente aquelas que se interessam pelos estudos das desigualdades sociais e dos processos de exclusão. Introduz o conceito de etnografia e desenvolve aspectos que envolvem o trabalho etnográfico, informando que fazer etnografia implica em: 1) preocupar-se com uma análise holística ou dialética da cultura entendida; 2) introduzir os atores. sociais com uma participação ativa e dinâmica e modificadora das estruturas sociais; e 3) preocupar-se em revelar as relações e interações significativas de modo a desenvolver a reflexividade sobre a ação de pesquisar. Concluí que alguns cuidados de vem orientar o pesquisador - a proposta de pesquisa, o período despendido no campo, a descrição densa e minuciosa dos dados e, finalmente, a ética na pesquisa.', '["ethnography","qualitative research","social inequality","social exclusion","researcher reflexivity","researcher ethics","fieldwork"]', '10.7476/9788578791902.0003', NULL, 'https://doi.org/10.7476/9788578791902.0003', 'https://doi.org/10.7476/9788578791902.0003', NULL, NULL, NULL, 52, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W205310263', 'https://openalex.org/W205310263', 'Integrative review: what is it? How to do it?', NULL, '["Marcela Tavares de Souza","Michelly Dias da Silva","Rachel de Carvalho"]', 'Einstein (São Paulo)', 'SciELO Brasil', 'scielo-br', 2010, '2010-03-01', 'en', 'article', 'social-sciences', 'Ciencias Sociales y Educación', 'Decision Sciences', 'INTRODUCTION: The integrative review is the methodology that provides synthesis of knowledge and applicability of results of significant studies to practice. OBJECTIVE: To present the phases of an integrative review and the relevant aspects to be taken into account when using this methodological resource. METHODS: This study was based on bibliographic search and on the experience of the authors when performing an integrative review. RESULTS: Presentation of the six stages of the integrative review process: preparing the guiding question, searching or sampling the literature, data collection, critical analysis of the studies included, discussion of results and presentation of the integrative review. CONCLUSIONS: Considering the need to assure care based on scientific evidence, the integrative review has been identified as a unique tool in healthcare for it synthesizes investigations available on the given topic and guides practice based on scientific knowledge.', '["integrative review","review methodology","evidence-based practice","evidence synthesis","literature searching","critical appraisal of studies","research question formulation"]', '10.1590/s1679-45082010rw1134', NULL, 'https://doi.org/10.1590/s1679-45082010rw1134', 'https://www.scielo.br/j/eins/a/ZQTBkVJZqcWrTT34cXLjtBx/?lang=en&format=pdf', NULL, NULL, NULL, 5694, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-z3529', 'z3529', 'Catálogo de plantas e fungos do Brasil - Vol. 1', NULL, '["Rafaela Campostrini Forzza","Paula Moraes Leitman","Andréa Ferreira da Costa","Aníbal Alves de Carvalho Júnior","Ariane Luna Peixoto","Bruno Machado Teles Walter","Carlos Eduardo de Mattos Bicudo","DANIELA CRISTINA ZAPPI"]', 'Instituto de Pesquisa Jardim Botânico do Rio de Janeiro eBooks', 'SciELO Books', 'books', 2010, '2010-01-01', 'es', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', '"Parabenizo a todos os botânicos que contribuíram para completar o presente catálogo. O Brasil é o país que provavelmente possui a maior flora do mundo, portanto, a produção de uma lista completa dessa flora é uma extensa tarefa. Os coordenadores mobilizaram uma grande equipe de pessoas para compilar a lista, e é ótimo ver que este projeto, diferentemente do que se observa em outros países, foi coordenado no Brasil. Isto demonstra o alto nível e a capacidade da comunidade botânica brasileira que se desenvolveu rapidamente nas últimas décadas. Este catálogo, por ter sido preparado na sua maioria por especialistas dos grupos estudados, mostra quais espécies são correntemente aceitas pelos botânicos envolvidos. As espécies foram padronizadas por meio da citação de materiais-voucher, a maioria dos quais foi coletada por brasileiros e está alojada em herbários do Brasil. A informação a respeito da distribuição geográfica de cada espécie será extremamente útil para fins de conservação, e é interessante notar o número expressivo de espécies endêmicas do Brasil. Este catálogo certamente será utilizado por estudantes de diversas áreas envolvendo botânica, ecologia e outras, e tenho certeza de que a sua existência estimulará futuras pesquisas a respeito de plantas brasileiras e que a sua versão online o manterá atualizado. O desafio agora é conservar os muitos ecossistemas diferentes nos quais estas espécies ocorrem, para manter a diversidade botânica do país." (trecho retirado do Prefácio do livro)', '["Brazilian flora","plant species checklist","fungi","species distribution","endemic species","voucher specimens","herbarium collections"]', '10.7476/9788560035083', NULL, 'https://books.scielo.org/id/z3529', 'https://books.scielo.org/id/z3529/pdf/forzza-9788560035083.pdf', NULL, 'https://books.scielo.org/id/z3529/cover/cover_thumbnail.jpeg', NULL, 190, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-mmtct', 'mmtct', 'Os africanos no Brasil', NULL, '["Raymundo Nina Rodrigues"]', 'Centro Edelstein eBooks', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'É a um ensaio de sistematização destes estudos que consagro o presente livro, destinando-o ao conhecimento de uma das preliminares do problema, a história dos Negros colonizadores. [trecho retirado da introdução do livro]', '["African colonization","African diaspora","colonial Brazil","race relations"]', '10.7476/9788579820106', NULL, 'https://books.scielo.org/id/mmtct', 'https://books.scielo.org/id/mmtct/pdf/rodrigues-9788579820106.pdf', NULL, 'https://books.scielo.org/id/mmtct/cover/cover_thumbnail.jpeg', NULL, 179, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W1588748712', 'https://openalex.org/W1588748712', 'O local do testemunho', NULL, '["Márcio Seligmann-Silva"]', 'Editora da Unicamp eBooks', 'Red SciELO', 'scielo-network', 2010, '2010-11-23', 'pt', 'chapter', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Leo Spitzer, em um pequeno artigo sobre o termo «témoin», publicado em 1938, já destacara que com este termo Nous sommes donc en présence d''un des nombreux cas ou celui qui exerce une fonction est confundu avec celle-ci (cf.esp.un cura, fr.guide [...]).Peut-être pourrait-on inférer de la coexistence des deux sens, qu''il s''agit pas à proprement dire de deux sens, mais que le personnage et son rôle ne sont pas distincts dans la conscience de l''individu parlant.', '["witness testimony","witnesses","witness function","Leo Spitzer","roles and functions"]', '10.7476/9788526816473.0008', NULL, 'https://doi.org/10.7476/9788526816473.0008', 'https://revistas.ufrj.br/index.php/metamorfoses/article/download/21820/12159', NULL, NULL, NULL, 56, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-b7spy', 'b7spy', 'A pluriatividade na agricultura familiar', NULL, '["Sérgio Schneider"]', 'Editora da UFRGS eBooks', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro se propõe a examinar as relações da agricultura familiar com a emergência e a consolidação das atividades não-agrícolas no espaço rural e a formação de unidades produtivas crescentemente identificadas com a pluriatividade das famílias rurais. Neste sentido, agrega-se, às pesquisas que vêm sendo realizadas para aprofundar os conhecimentos sobre a agricultura familiar e suas possibilidades de desenvolvimento social e econômico no espaço rural. Nos anos recentes, vários cientistas sociais vêm dedicando seus estudos e análises às formas familiares. Esse trabalho intelectual tem sido desenvolvido sob variados focos, podendo-se extrair pelos menos dois ensinamentos. O primeiro indica a existência de diferentes estratégias sociais e econômicas através das quais as populações, grupos e indivíduos identificados com a agricultura familiar vêm viabilizando sua reprodução social e sobrevivência econômica nas sociedades contemporâneas. O segundo e maior aprendizado demonstra que, pelo menos nas nações mais desenvolvidas, o Estado tem sido o maior responsável pela manutenção de políticas públicas e formas de apoio à expansão e à consolidação das unidades que se organizam e estruturam com base no trabalho familiar. A presente obra situa-se no primeiro veio citado, alinhando-se às pesquisas cujo objetivo tem sido o de demonstrar os mecanismos e as estratégias que viabilizam, e em certos casos até ampliam e fortalecem, as formas familiares no campo.', '["family farming","pluriactivity","rural households","family forms","social reproduction","economic survival","rural development"]', '10.7476/9788538603894', NULL, 'https://books.scielo.org/id/b7spy', 'https://books.scielo.org/id/b7spy/pdf/schneider-9788538603894.pdf', NULL, 'https://books.scielo.org/id/b7spy/cover/cover_thumbnail.jpeg', NULL, 336, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-p5', 'p5', 'O Português Afro-Brasileiro', NULL, '["Dante Lucchesi","Alan Norman Baxter","Ilza Maria de Oliveira Ribeiro"]', 'EDUFBA eBooks', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Organizado pelos professores Dante Lucchesi e Ilza Ribeiro, da Universidade Federal da Bahia, e pelo professor Allan Baxter, da Universidade de Macau, teve a colaboração de vários autores, professores de outras universidades do mesmo Estado, além de mestres, doutores e pós-graduandos, em geral oriundos daquela mesma universidade, integrantes do grupo de pesquisa ali constituído, e que vêm se dedicando ao estudo da realidade lingüística brasileira. Baseado na análise de amostras da fala de algumas comunidades rurais afro-brasileiras isoladas, no caso, quatro comunidades do Estado da Bahia - Helvécia, Cinzento, Rio de Contas e Sapé -, o livro apresenta os resultados obtidos pela aplicação de modelos teóricos que transitam da gerativa, de princípios e parâmetros, à sociolingüística variacionista, dentro daquela linha fecunda inaugurada pelo Prof. Tarallo nos anos oitenta.Dividido em duas partes, são apresentados, na primeira, os fundamentos teóricos e metodológicos nos quais se baseou a pesquisa e também o contexto sócio histórico das comunidades analisadas. Na segunda parte, são isolados dezesseis ''pontos-diagnósticos'' (apropriando-me da expressão utilizada pelo Professor Aryon Rodrigues em sua análise comparativa das línguas tupi-guarani), pelos quais se pode tanto esboçar um retrato das variedades vernáculas das comunidades pesquisadas, quanto levantar hipóteses, já mais bem fundadas, sobre a história do contato do português com as línguas africanas em território brasileiro.', '["Afro-Brazilian Portuguese","isolated rural areas","Rio de Contas","sape","Bahia","sociolinguistic variation","generative linguistics"]', '10.7476/9788523208752', NULL, 'https://books.scielo.org/id/p5', 'https://books.scielo.org/id/p5/pdf/lucchesi-9788523208752.pdf', NULL, 'https://books.scielo.org/id/p5/cover/cover_thumbnail.jpeg', NULL, 154, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-83rmh', '83rmh', 'Rumores de festa: o sagrado e o profano na Bahia', NULL, '["Ordep José Trindade Serra"]', 'EDUFBA eBooks', 'SciELO Books', 'books', 2009, '2009-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esse livro aborda o cambiante movimento das festas populares baianas, um fenômeno que hoje suscita grande interesse de estudiosos e do público em geral. Ele chama a atenção para transformações, fazendo referências a etapas anteriores e esboçando tentativas de sondar desenvolvimentos futuros. Preenche importante lacuna na bibliografia acerca do tema abordado.', '["popular festivals","Bahia","sacred and profane","religious festivals","festival transformation","popular culture","Afro-Brazilian religions"]', '10.7476/9788523212315', NULL, 'https://books.scielo.org/id/83rmh', 'https://books.scielo.org/id/83rmh/pdf/serra-9788523212315.pdf', NULL, 'https://books.scielo.org/id/83rmh/cover/cover_thumbnail.jpeg', NULL, 35, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-cghr3', 'cghr3', 'Partidos e sindicatos: escritos de sociologia política', NULL, '["Leôncio Martins Rodrigues"]', 'Centro Edelstein eBooks', 'SciELO Books', 'books', 2009, '2009-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro reúne um conjunto de artigos sobre dois temas que tendem a se aproximar: o do partido e o do sindicalismo. O primeiro, “A composição social das lideranças do PT”, foi escrito em março de 1989, e apresentado em abril no Colóquio Franco-Brasileiro de Ciências Sociais realizado em Paris. Esta é sua primeira publicação. O segundo artigo, “Paradoxos do sindicalismo”, foi publicado no Jornal da Tarde, em 5 de outubro de 1985. Apenas uma ou outra correção foi introduzida.', '["political parties","trade unions","Brazilian politics","political sociology"]', '10.7476/9788579820267', NULL, 'https://books.scielo.org/id/cghr3', 'https://books.scielo.org/id/cghr3/pdf/rodrigues-9788579820267.pdf', NULL, 'https://books.scielo.org/id/cghr3/cover/cover_thumbnail.jpeg', NULL, 28, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-yjxnr', 'yjxnr', 'Design e ergonomia: aspectos tecnológicos', NULL, '["Luís Carlos Paschoarelli","Marizilda dos Santos Menezes"]', 'Editora UNESP eBooks', 'SciELO Books', 'books', 2009, '2009-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A evolução tecnológica observada nas últimas décadas representa a materialização da criatividade humana no desenvolvimento de ambientes, produtos e sistemas, os quais trouxeram muitos benefícios, com destaque para o aumento na economia global, o aumento na expectativa de vida das pessoas, as possibilidades de comércio, interações e comunicações, entre outros.Mas essa mesma evolução também vem resultando em alguns problemas, os quais preocupam tecnólogos, pesquisadores e entidades de proteção aos consumidores sob, pelo menos, dois aspectos bastante pragmáticos: o impacto negativo de muitas dessas tecnologias sobre o meio ambiente e os problemas das interfaces tecnológicas, as quais geram constrangimentos, acidentes e frustração aos consumidores e usuários.Este segundo aspecto está em discussão desde o fi nal do século passado, quando os termos ergonomia, usabilidade, acessibilidade e design universal tomaram conta das questões científi cas em torno do design de produtos e sistemas.A discussão em torno desses temas, por vezes, parece antiquada para os dias atuais, mas de fato envolve questões ainda não respondidas pela comunidade científica.Ao design, ainda resta a questão: como a ergonomia pode contribuir para minimizar os impactos negativos da evolução tecnológica de produtos, sistemas e ambientes?', '["design","human factors","usability","accessibility","universal design","user frustration","consumer protection"]', '10.7476/9788579830013', NULL, 'https://books.scielo.org/id/yjxnr', 'https://books.scielo.org/id/yjxnr/pdf/paschoarelli-9788579830013.pdf', NULL, 'https://books.scielo.org/id/yjxnr/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-qqx82', 'qqx82', 'Agricultura, cooperativas e multinacionais', NULL, '["Odaci Luiz Coradini","Antoinette Fredericq"]', 'Centro Edelstein eBooks', 'SciELO Books', 'books', 2009, '2009-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Abordando aspectos diferentes, os dois estudos focalizam mecanismos de interpenetração crescente entre o capital agroindustrial e os produtores rurais, as estratégias que os diversos agentes utilizam e o papel das cooperativas dentro desse complexo jogo de forças. [...] [trecho retirado da apresentação do livro]', '["agricultural cooperatives","multinational corporations","rural farmers","power relations"]', '10.7476/9788579820090', NULL, 'https://books.scielo.org/id/qqx82', 'https://books.scielo.org/id/qqx82/pdf/coradini-9788579820090.pdf', NULL, 'https://books.scielo.org/id/qqx82/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-rp6gk', 'rp6gk', 'Educação inclusiva, deficiência e contexto social: questões contemporâneas', NULL, '["Díaz, Félix","Bordas, Miguel","Galvão, Nelma","Miranda, Theresinha"]', 'EDUFBA', 'SciELO Books', 'books', 2009, '2009', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'O enfoque desta obra decorre da relevância que o contexto sociocultural em que a pessoa está inserida serve de parâmetro para classificá-la como normal e anormal, além de enfatizar o ensino e a escola, bem como as formas e condições de aprendizado. Esta perspectiva, ao invés de procurar no aluno a origem de um problema, define o tipo de resposta educativa e de recursos e apoios que a escola deve proporcionar a esse aluno para que ele obtenha o sucesso escolar.', '[]', '10.7476/9788523209285', '9788523206512', 'https://books.scielo.org/id/rp6gk', 'https://books.scielo.org/id/rp6gk/pdf/diaz-9788523209285.pdf', 'https://books.scielo.org/id/rp6gk/epub/diaz-9788523209285.epub', 'https://books.scielo.org/id/rp6gk/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'edufba');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-7nrc4', '7nrc4', 'Gabriela, bahiana de todas as cores: as imagens das capas e suas influências culturais', NULL, '["Caldas, Sônia Regina de Araújo"]', 'EDUFBA', 'SciELO Books', 'books', 2009, '2009', 'pt', 'book', 'humanities', 'Humanidades y Artes', NULL, 'O ensaio cumpre o papel de proporcionar aos estudiosos de literatura uma visão pormenorizada das ilustrações e das capas de várias edições do romance Gabriela, cravo e canela, no Brasil e no mundo. O grande desafio é promover incessantemente um canal de experiências e de intercâmbios culturais, incentivando e sistematizando a produção de estudos, teses e ensaios realizados a partir da obra de Jorge Amado.', '[]', '10.7476/9788523209339', '9788523206499', 'https://books.scielo.org/id/7nrc4', 'https://books.scielo.org/id/7nrc4/pdf/caldas-9788523209339.pdf', 'https://books.scielo.org/id/7nrc4/epub/caldas-9788523209339.epub', 'https://books.scielo.org/id/7nrc4/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'edufba');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-cjnwk', 'cjnwk', 'Estado e classes sociais na agricultura brasileira', NULL, '["Bernardo Sorj"]', 'Centro Edelstein eBooks', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[...] nosso estudo focaliza um primeiro ciclo histórico de expansão agroindustrial, caracterizado por estar ligado especialmente a produtos de exportação. Na atualidade, abre-se um novo ciclo de expansão agroindustrial na direção de produtos alimentícios e matérias-primas para o mercado interno.', '["Brazilian agriculture","agroindustrial expansion","agricultural exports","food products","agricultural raw materials","domestic market","agricultural history"]', '10.7476/9788599662281', NULL, 'https://books.scielo.org/id/cjnwk', 'https://books.scielo.org/id/cjnwk/pdf/sorj-9788599662281.pdf', NULL, 'https://books.scielo.org/id/cjnwk/cover/cover_thumbnail.jpeg', NULL, 169, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-4ndgv', '4ndgv', 'Reforma sanitária Brasileira: contribuição para a compreensão e crítica', NULL, '["Jairnilson Silva Paim"]', 'Editora FIOCRUZ eBooks', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A Reforma Sanitária Brasileira como um fenômeno sócio-histórico Pensando a sociedade e o estado no Brasil Conjuntura da transição democrática: da criação do Cebes à Constituição O nascimento do Cebes O Programa Nacional de Serviços Básicos de Saúde (Prev-Saúde) O Plano de Reorientação da Assistência Médica no Âmbito da Previdência Social (o Plano do Conasp) As Ações Integradas de Saúde (AIS) A 8ª Conferência Nacional de Saúde A Comissão Nacional da Reforma Sanitária (CNRS) Sistema Unificado e Descentralizado de Saúde (SUDS) O processo constituinte Reforma Sanitária como objeto de reflexão teórico-conceitual Concepções de saúde Concepções de práticas de saúde e de organização de serviços', '["Brazilian health reform","health system organization","Cebes","National Health Conference","CNRS","sustainable urban drainage systems","democratic transition"]', '10.7476/9788575413593', NULL, 'https://books.scielo.org/id/4ndgv', 'https://books.scielo.org/id/4ndgv/pdf/paim-9788575413593.pdf', NULL, 'https://books.scielo.org/id/4ndgv/cover/cover_thumbnail.jpeg', NULL, 162, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-4fdcs', '4fdcs', 'El desafío latinoamericano: cohesión social y democracia', NULL, '["Bernardo Sorj","Danilo Martuccelli"]', 'Centro Edelstein eBooks', 'SciELO Books', 'books', 2008, '2008-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Entender la dinámica a través de la cual se construye la cohesión social en América Latina supone una inversión de perspectiva frente a la tendencia dominante que enfatiza los problemas sociales que afligen el continente. Si desconocer estas dificultades sería caer en apologías conservadoras, para entender cómo nuestras sociedades generan cohesión social no podemos dejar de identificar igualmente los enormes recursos positivos de integración y de creatividad socio-cultural existentes en nuestras sociedades.', '["social cohesion","democracy","Latin America","social integration"]', '10.7476/9788579820793', NULL, 'https://books.scielo.org/id/4fdcs', 'https://books.scielo.org/id/4fdcs/pdf/sorj-9788579820793.pdf', NULL, 'https://books.scielo.org/id/4fdcs/cover/cover_thumbnail.jpeg', NULL, 36, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-b4km4', 'b4km4', 'Sociedade política no Brasil pós-64', NULL, '["Bernardo Sorj","María Herminia Tavarés de Almeida"]', 'Centro Edelstein eBooks', 'SciELO Books', 'books', 2008, '2008-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[...] acreditamos que o livro constitui pelo menos um esforço no sentido de apresentar uma visão do conjunto e relativamente coerente das transformações em curso nas últimas duas décadas na sociedade brasileira. Nosso objetivo e desejo é que possa tornar-se referência e incentivo para novos e melhores estudos, capazes de proporcionar uma imagem sintética da complexa estrutura social brasileira. [trecho retirado da apresentação do livro]', '["post-1964 Brazil","social change","Brazilian society","social structure"]', '10.7476/9788599662632', NULL, 'https://books.scielo.org/id/b4km4', 'https://books.scielo.org/id/b4km4/pdf/sorj-9788599662632.pdf', NULL, 'https://books.scielo.org/id/b4km4/cover/cover_thumbnail.jpeg', NULL, 20, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W1994682895', 'https://openalex.org/W1994682895', 'The PICO strategy for the research question construction and evidence search', NULL, '["Cristina Mamédio da Costa Santos","Cibele Andrucioli de Mattos Pimenta","Moacyr Roberto Cucê Nobre"]', 'Revista Latino-Americana de Enfermagem', 'SciELO Brasil', 'scielo-br', 2007, '2007-06-01', 'en', 'article', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Evidence based practice is the use of the best scientific evidence to support the clinical decision making. The identification of the best evidence requires the construction of an appropriate research question and review of the literature. This article describes the use of the PICO strategy for the construction of the research question and bibliographical search.', '["PICO","research question formulation","evidence-based practice","literature searching","bibliographic database searching","clinical decision-making"]', '10.1590/s0104-11692007000300023', NULL, 'https://doi.org/10.1590/s0104-11692007000300023', 'https://www.scielo.br/j/rlae/a/CfKNnz8mvSqVjZ37Z77pFsy/?lang=en&format=pdf', NULL, NULL, NULL, 2953, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W2887006492', 'https://openalex.org/W2887006492', 'Povos indígenas no Brasil', NULL, '["Ricardo Ventura Santos","Carlos Ε. A. Coimbra","Andrey Moreira Cardoso"]', 'Editora FIOCRUZ eBooks', 'Red SciELO', 'scielo-network', 2007, '2007-01-01', 'pt', 'chapter', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A Organização das Nações Unidas (ONU) apresenta a seguinte definição de "indígena":Comunidades, povos ou nações indígenas são aqueles que, apresentando uma continuidade com sociedades pré-coloniais que se desenvolveram em seus territórios no passado, consideram-se diferentes de outros segmentos que, na atualidade, predominam nesses territórios, ou em parte deles.Constituem segmentos não dominantes da sociedade e manifestam o compromisso de preservar e desenvolver suas culturas e transmitir para gerações futuras seus territórios ancestrais, suas identidades étnicas, tendo por base sua existência contínua como povos, de acordo com seus padrões culturais, instituições sociais e sistemas jurídicos.Essa continuidade histórica pode se manifestar, por um período que se estende até o presente, de um ou mais dos seguintes fatores:', '["indigenous peoples","indigenous identity","ancestral land","ethnic identity","cultural preservation","precolonial societies","indigenous law"]', '10.7476/9788575415870.003', NULL, 'https://doi.org/10.7476/9788575415870.003', 'https://doi.org/10.7476/9788575415870.003', NULL, NULL, NULL, 51, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-f5jk5', 'f5jk5', 'Memória e formação de professores', NULL, '["Nascimento, Antônio Dias","Hetkowski, Tânia Maria"]', 'EDUFBA', 'SciELO Books', 'books', 2007, '2007', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'Gira em torno de duas temáticas: memória e educação e formação de professores. A primeira diz respeito à identificação dos processos civilizatórios e o modo como se articulam com os processos educativos no que se refere à história da educação, pluralidade cultural, movimentos sociais, representação social e inclusão. A segunda aborda a importância dos estudos e pesquisas que contribuem para a formação de novos agentes destinados ao papel de formadores de um mundo mais humano e justo.', '[]', '10.7476/9788523209186', '9788523204846', 'https://books.scielo.org/id/f5jk5', 'https://books.scielo.org/id/f5jk5/pdf/nascimento-9788523209186.pdf', 'https://books.scielo.org/id/f5jk5/epub/nascimento-9788523209186.epub', 'https://books.scielo.org/id/f5jk5/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'edufba');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-7h7yn', '7h7yn', 'Vírus, mosquitos e modernidade: a febre amarela no Brasil entre ciência e política', NULL, '["Löwy, Ilana"]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 2006, '2006', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'A autora não se limita a apresentar a história da febre amarela no Brasil, mas uma reflexão sobre uma fase crucial da história da doença.
Para melhor ilustrar essa reflexão, o livro mostra sucessivos cenários que permitem demonstrar as dimensões da transferência de conhecimentos e práticas científicas entre ‘centro’ e ‘periferia’, pois era de fato importante examinar as relações entre o saber científico universal e a percepção da doença tanto pelos pacientes quanto pelos médicos.', '[]', '10.7476/9788575412398', '8575410628', 'https://books.scielo.org/id/7h7yn', 'https://books.scielo.org/id/7h7yn/pdf/lowy-9788575412398.pdf', 'https://books.scielo.org/id/7h7yn/epub/lowy-9788575412398.epub', 'https://books.scielo.org/id/7h7yn/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W1592012430', 'https://openalex.org/W1592012430', 'As origens da reforma sanitária e do SUS', NULL, '["Sarah Escorel","Dilene Raimundo do Nascimento","Flávio Coelho Edler"]', 'Editora FIOCRUZ eBooks', 'Red SciELO', 'scielo-network', 2005, '2005-01-01', 'pt', 'chapter', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'As Origens da Reforma Sanitária e do SUS 59Este artigo pretende descrever o processo histórico que deu origem ao Sistema Único de Saúde (SUS) no Brasil, analisando o movimento pela Reforma Sanitária.O foco desta análise se concentra entre meados da década de 1970, quando, ainda em plena ditadura, se articula a agenda política do movimento, até 1990, momento em que a Lei Orgânica da Saúde (LOS 8.080) consolidou, apesar dos vetos do governo Collor, objetivos, atribuições, diretrizes, princípios, organização, financiamento e planejamento do SUS, em conformidade com o capítulo da Saúde da nova Constituição Brasileira, de 1988.Para se compreender o significado e o alcance do movimento de Reforma Sanitária, convém analisá-lo a partir dos marcos da história política brasileira onde transcorreu essa luta pela elevação dos padrões de saúde da população.Nesta síntese panorâmica dos problemas próprios ao campo da saúde pública e da assistência médica, é apresentada uma periodização que se articula com os marcos políticos mais gerais.Como será assinalado adiante, algumas das tendências do sistema nacional de saúde mantiveram-se ao longo do período, enquanto outras sofreram inflexões ou transformações radicais.Primeira fase do regime autoritário e a articulação do movimento sanitário (1964)(1965)(1966)(1967)(1968)(1969)(1970)(1971)(1972)(1973)(1974) Como se deu em outras ocasiões na história do Brasil, o golpe militar de 1964 abreviou o confronto político entre forças civis conservadoras e progressistas.Dessa vez, a curta experiência democrática foi abortada sob duas alegações', '["health care reform","history of public health","health movement","Brazilian Constitution of 1988","military dictatorship","Collor government","health care financing"]', '10.7476/9788575413678.0004', NULL, 'https://doi.org/10.7476/9788575413678.0004', 'https://doi.org/10.7476/9788575413678.0004', NULL, NULL, NULL, 45, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-qdgqt', 'qdgqt', 'Demografia dos povos indígenas no Brasil', NULL, '["Pagliaro, Heloísa","Azevedo, Marta Maria","Santos, Ricardo Ventura"]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 2005, '2005', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Esta obra de caráter interdisciplinar reúne estudos atuais sobre a demografia indígena no Brasil. O fato de ser interdisciplinar é enriquecedor, uma vez que admite a necessidade de diálogo e correlação entre os diferentes campos do saber, como a demografia, a antropologia e a epidemiologia, que tratam de um assunto para dizer no mínimo desconhecido da maioria da população leiga: onde estão e quem são os índios do Brasil? É a partir dessa tentativa de diálogo que os autores procuraram reunir nesta obra artigos que versam sobre diferentes temas como fecundidade, comportamento reprodutivo e mortalidade de populações indígenas.', '[]', '10.7476/9788575412541', '8575410563', 'https://books.scielo.org/id/qdgqt', 'https://books.scielo.org/id/qdgqt/pdf/pagliaro-9788575412541.pdf', 'https://books.scielo.org/id/qdgqt/epub/pagliaro-9788575412541.epub', 'https://books.scielo.org/id/qdgqt/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-sgprn', 'sgprn', 'Em busca da boa morte: antropologia dos cuidados paliativos', NULL, '["Rachel Aisengart Menezes"]', 'Editora FIOCRUZ eBooks', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Fruto de um trabalho etnográfico, o livro Em Busca da Boa Morte, de Rachel Aisengart Menezes, aborda o novo ideário, conhecido como paliativista, que coloca em questão a morte fria e desprotegida no hospital – desse modo, o que se procura aqui é refletir acerca de um processo de mudança cultural, de contornos ainda pouco precisos, mas que, inegavelmente, procura humanizar o momento da morte, encarando a relação médico-paciente sob um outro ponto de vista . Trata-se de uma obra que traz à tona questões sobre a Ética no mundo contemporâneo, que banaliza a morte ou simplesmente não fala dela. Desse modo, o novo ideário constitui-se como uma resposta possível, mesmo que ainda ligada, à onisciência e onipresença da Medicina, quando o discurso médico já não possui respostas, conscientizando-se das suas limitações.', '["palliative care","good death","humanization of death","medical ethics","physician-patient relationship","limits of medicine"]', '10.7476/9786557081129', NULL, 'https://books.scielo.org/id/sgprn', 'https://books.scielo.org/id/sgprn/pdf/menezes-9786557081129.pdf', NULL, 'https://books.scielo.org/id/sgprn/cover/cover_thumbnail.jpeg', NULL, 190, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-wcgvd', 'wcgvd', 'O Recém-nascido de Alto Risco: teoria e prática do cuidar', NULL, '["Moreira, Maria Elisabeth Lopes","Lopes, José Maria de Andrade","Carvalho, Manoel de"]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 2004, '2004', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Seleção de textos abrangentes e atuais cobrindo tanto as principais patologias e intervenções relativas aos recém-nascidos gravemente enfermos quanto as áreas profissionais ao tema relacionadas. Registra mais de 20 anos de experiência de uma das mais competentes equipes de neonatologia do País - a do Instituto Fernandes Figueira/Fiocruz -, com sua inegável contribuição no campo da saúde da mulher e da criança. Referência fundamental para neonatologistas e para todos os envolvidos na assistência a recém-nascidos de alto risco.', '[]', '10.7476/9788575412374', '8575410547', 'https://books.scielo.org/id/wcgvd', 'https://books.scielo.org/id/wcgvd/pdf/moreira-9788575412374.pdf', 'https://books.scielo.org/id/wcgvd/epub/moreira-9788575412374.epub', 'https://books.scielo.org/id/wcgvd/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-6gsm7', '6gsm7', 'Depressão: clínica, crítica e ética', NULL, '["Coser, Orlando"]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 2003, '2003', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Neste livro podemos entender a complexidade de questões associadas à depressão, desde suas origens como subproduto do contexto cultural contemporâneo ao horizonte mercadológico em que é alardeada como ''mal do século'' e fármacos são anunciados como ''milagrosos''. É nesse contexto de alarde e extrema variedade de informações pouco precisas e confiáveis que ele se torna importante e oportuno. O autor, contemplando a necessidade de precisar o conceito de depressão para problematizar criticamente tal processo, nos convida a repensar a clínica e sua respectiva ética, revitalizando o saber e a prática do psiquiatra e do psicanalista e a própria noção de doença como experiência vivida.', '[]', '10.7476/9788575412558', '857541030X', 'https://books.scielo.org/id/6gsm7', 'https://books.scielo.org/id/6gsm7/pdf/coser-9788575412558.pdf', 'https://books.scielo.org/id/6gsm7/epub/coser-9788575412558.epub', 'https://books.scielo.org/id/6gsm7/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-d5t55', 'd5t55', 'O Clássico e o Novo: tendências, objetos e abordagens em ciências sociais e saúde', NULL, '["Goldenberg, Paulete","Marsiglia, Regina Maria Giffoni","Gomes, Mara Helena de Andréa"]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 2003, '2003', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Tratando de temas, como a cultura e a subjetividade, as questões éticas da atualidade, a qualidade de vida no mundo contemporâneo etc., O Clássico e o Novo é o fruto de trabalhos apresentados no 2o Congresso Brasileiro de Ciências Sociais em Saúde, e reúne uma gama dos mais qualificados profissionais que tratam de diferentes temas, intencionando uma perspectiva multidisciplinar. Partindo do pressuposto de que dentro da própria área das Ciências Sociais há um processo de fragmentação que vem exigindo cada vez mais novas interlocuções interdisciplinares, procura-se aqui estabelecer um diálogo profícuo entre este campo do saber e a área da saúde. Dessa forma, ao abordar questões relacionadas à área da saúde, este livro se constitui como leitura obrigatória para os profissionais de saúde coletiva, introduzindo diferentes e instigantes propostas de reflexão para a saúde na atualidade.', '[]', '10.7476/9788575412510', '8575410253', 'https://books.scielo.org/id/d5t55', 'https://books.scielo.org/id/d5t55/pdf/goldenberg-9788575412510.pdf', 'https://books.scielo.org/id/d5t55/epub/goldenberg-9788575412510.epub', 'https://books.scielo.org/id/d5t55/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-bsmtd', 'bsmtd', 'Epidemiologia e saúde dos povos indígenas no Brasil', NULL, '["Coimbra Jr., Carlos E. A.","Santos, Ricardo Ventura","Escobar, Ana Lúcia"]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 2003, '2003', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Rica seleção de textos e experiências sobre a questão da saúde indígena no Brasil, originários de discussão em oficina de trabalho ocorrida no V Congresso Brasileiro de Epidemiologia (Curitiba, 2002). Escrito por pesquisadores estudiosos das mais diferentes vertentes do assunto, traz importante e inovadora contribuição a tema que vem emergindo como de grande importância no âmbito da saúde coletiva no Brasil nos últimos anos. Oferece um amplo panorama, detalhado e atualizado, da saúde indígena no País, contemplando reflexões com base nas diversas áreas do conhecimento que compõem a saúde coletiva.', '[]', '10.7476/9788575412619', '8575410229', 'https://books.scielo.org/id/bsmtd', 'https://books.scielo.org/id/bsmtd/pdf/coimbra-9788575412619.pdf', 'https://books.scielo.org/id/bsmtd/epub/coimbra-9788575412619.epub', 'https://books.scielo.org/id/bsmtd/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W2152863375', 'https://openalex.org/W2152863375', 'International Classification of Functioning, Disability and Health (ICF) 2001', NULL, '["María Teresa Jiménez-Buñuales","Paulino González Diego","José M.ª Martín Moreno"]', 'Revista Española de Salud Pública', 'Red SciELO', 'scielo-network', 2002, '2002-08-01', 'es', 'article', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'The approach which had been being employed to date for dealing with and classifying those aspects related to health and disability have been revised and updated thanks to the World Health Organization (WHO) having drafted the International Classification of Functioning, Disability and Health, which has now been accepted 191 countries after revamping the prior model and reaching a consensus regarding a new international model for describing and measuring health and disability. As background information, it must be recalled that the Classification of Impairments, Disabilities and Handicaps (CIDH) previously in effect was first published by the WHO in 1980. The process of revising this classification has resulted in some changes of far-reaching importance. The change in the name has been aimed at reflecting the wish to replace the negative perspective of impairments, disabilities and handicaps for a more neutral view of structure and function, considering the positive perspectives of activities and of participation. Another new aspect has been that of including a section related to environmental factors in recognition of their importance, given that by interacting with the health condition they may give rise to a disability, or, at the opposite end of the scale, may restore functioning. The data available has enabled the WHO make estimates including that of some 500 million years of life being lost annually due to disabilities related to health problems, which totals over one half of the years lost annually due to premature deaths. The main objective of this new classification is that of providing the conceptual framework by means of unified, standardized language with a view to of the underlying challenges, setting out a valuable instrument of practical use in public health.', '["International Classification of Functioning, Disability and Health","disability classification","structure and function","activities and participation","environmental factors","years of life lost","disability assessment"]', '10.1590/s1135-57272002000400002', NULL, 'https://doi.org/10.1590/s1135-57272002000400002', 'https://scielosp.org/article/ssm/content/raw/?resource_ssm_path=/media/assets/resp/v76n4/colabora.pdf', NULL, NULL, NULL, 3291, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W2010298762', 'https://openalex.org/W2010298762', 'El informe mundial sobre la violencia y la salud.', NULL, '["Etienne G. Krug","James A. Mercy","Linda L. Dahlberg","Anthony B. Zwi"]', 'Biomédica', 'Red SciELO', 'scielo-network', 2002, '2002-12-01', 'es', 'article', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'In 1996, the World Health Assembly declared violence a major public health issue. To follow up on this resolution, on October 3 this year, WHO released the first World Report on Violence and Health. The report analyses different types of violence including child abuse and neglect, youth violence, intimate partner violence, sexual violence, elder abuse, self-directed violence, and collective violence. For all these types of violence, the report explores the magnitude of the health and social effects, the risk and protective factors, and the types of prevention efforts that have been initiated. The launch of the report will be followed by a 1-year Global Campaign on Violence Prevention, focusing on implementation of the recommendations. This article summarises some of the main points of the world report.', '["violence and health","child abuse","youth violence","intimate partner violence","sexual violence","elder abuse","self-directed violence"]', '10.7705/biomedica.v22isupp2.1182', NULL, 'https://doi.org/10.7705/biomedica.v22isupp2.1182', 'https://revistabiomedica.org/index.php/biomedica/article/download/1182/1297', NULL, NULL, NULL, 1064, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-4cdf6', '4cdf6', 'O Rio em Movimento: quadros médicos e(m) história 1890 - 1920', NULL, '["Lopes, Myriam Bahia"]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 2001, '2001', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Fruto de ampla pesquisa historiográfica, o livro oferece uma (re)leitura sobre a Revolta da Vacina em um Rio de Janeiro ainda com características próprias dos primórdios republicanos. A autora trabalha com os diversos elementos que se aglutinaram para compor esse quadro da nossa história. A forma inovadora da escrita - narrativas entrecruzadas -, ilustrada  pelas representações plásticas da época, confirma a recusa a dar respostas acabadas a indagações, desvendando facetas inesperadas que fortificam qualquer explicação conclusiva a que se queira chegar. Resulta desse conjunto uma vívida descrição do que foi o movimento dos revoltosos pelas ruas do Rio naqueles dias. Livro que, além de abrir novas perspectivas para os estudos sobre as questões urbanas, tem o mérito de atualizar o diálogo sobre o assunto.', '[]', '10.7476/9788575412756', '8585676604', 'https://books.scielo.org/id/4cdf6', 'https://books.scielo.org/id/4cdf6/pdf/lopes-9788575412756.pdf', 'https://books.scielo.org/id/4cdf6/epub/lopes-9788575412756.epub', 'https://books.scielo.org/id/4cdf6/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-7htrv', '7htrv', 'Os delírios da razão: médicos, loucos e hospícios (Rio de Janeiro, 1830-1930)', NULL, '["Engel, Magali Gouveia"]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 2001, '2001', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Trata das idéias e vivências da loucura presentes na cidade do Rio de Janeiro entre 1830 e 1930, período em que foi apropriada e transformada pelos alienistas em doença mental. Por meio da narrativa das várias tramas de personagens famosos por sua vesânia e aprisionados nas malhas da doença mental, a autora delineia um panorama histórico da loucura, passando pela análise das condições de enclausuramento às quais grande parte dos indivíduos suspeitos e/ou diagnosticados como doentes mentais ficariam sujeitos a partir da criação do Hospício de Pedro II. Fundamental para leigos e acadêmicos, assinala o momento em que os médicos brasileiros começariam a reivindicar para si a responsabilidade sobre a loucura, defendendo a necessidade da construção de hospícios onde os alienados mentais pudessem ser recolhidos e tratados convenientemente.', '[]', '10.7476/9788575412534', '8585676949', 'https://books.scielo.org/id/7htrv', 'https://books.scielo.org/id/7htrv/pdf/engel-9788575412534.pdf', 'https://books.scielo.org/id/7htrv/epub/engel-9788575412534.epub', 'https://books.scielo.org/id/7htrv/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-rmmbk', 'rmmbk', 'Salud y equidad: una mirada desde las ciencias sociales', NULL, '["Roberto Briceño‐León","Maria Cecília de Souza Minayo","Carlos Ε. A. Coimbra"]', 'Editora FIOCRUZ eBooks', 'SciELO Books', 'books', 2000, '2000-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A saúde da população mundial tem melhorado, porém, apesar do impressionante avanço tecnológico, ainda há graves problemas a superar - entre estes, o maior talvez seja a desigualdade. Diante de tal realidade, o tema da ''eqüidade em saúde'' mostra-se de extrema relevância, uma vez que trata-se de assunto que merece os enfoques político, econômico, social e cultural. Esta coletânea é produto de diversas investigações levadas a cabo por seus autores (reunidos durante o V Congresso Latino-Americano de Ciências Sociais e Medicina, na Venezuela) e pretende, sobretudo, ser uma contribuição para o sonho de construir uma sociedade mais eqüitativa, a partir da melhor compreensão dos determinantes sociais da saúde.', '["health equity","social determinants of health","health disparities","social justice","social sciences and health","health policy"]', '10.7476/9788575415122', NULL, 'https://books.scielo.org/id/rmmbk', 'https://books.scielo.org/id/rmmbk/pdf/briceno-9788575415122.pdf', NULL, 'https://books.scielo.org/id/rmmbk/cover/cover_thumbnail.jpeg', NULL, 63, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-4zb7w', '4zb7w', 'Um aprendiz de ciência', NULL, '["Chagas Filho, Carlos"]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 2000, '2000', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Carioca ''da gema'', sofisticado cosmopolita, bem-humorado e, ao mesmo, profundamente tocado pela simplicidade e pelas tradições das pequenas cidades mineiras e do mundo rural, o cientista e humanista Carlos Chagas Filho deixou, neste Um aprendiz de ciência, um delicioso relato de vivências, reflexões e realizações que são o testemunho do que há de mais significativo, na segunda metade do século XX, quanto à presença brasileira no campo das relações entre ciência, cultura, nacionalidade e cidadania.  A obra contém um belo encarte com fotos, cartas e textos que marcaram a vida do autor.', '[]', '10.7476/9788575412473', '8520910823', 'https://books.scielo.org/id/4zb7w', 'https://books.scielo.org/id/4zb7w/pdf/chagas-9788575412473.pdf', 'https://books.scielo.org/id/4zb7w/epub/chagas-9788575412473.epub', 'https://books.scielo.org/id/4zb7w/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-qxhc3', 'qxhc3', 'Reviravolta na saúde origem e articulação do movimento sanitário', NULL, '["Sarah Escorel"]', 'Editora FIOCRUZ eBooks', 'SciELO Books', 'books', 1999, '1999-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Um ''movimento de pessoas'' lutando por mudanças na maneira de olhar o paciente, a medicina e a política no setor. Uma verdadeira Reviravolta na Saúde, começada no movimento estudantil, no interior de movimentos médicos e na própria academia. Sarah Escorel detalha o início do movimento sanitário no Brasil, a partir do governo Figueiredo. Para isso, utilizou não somente documentos, mas depoimentos. É a história contada pelos próprios atores.', '["health movement","health policy","medical profession","student movement","Fernando Collor government","health politics"]', '10.7476/9788575413616', NULL, 'https://books.scielo.org/id/qxhc3', 'https://books.scielo.org/id/qxhc3/pdf/escorel-9788575413616.pdf', NULL, 'https://books.scielo.org/id/qxhc3/cover/cover_thumbnail.jpeg', NULL, 161, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-6p4jp', '6p4jp', 'Dos micróbios aos mosquitos: febre amarela e a revolução pasteuriana no Brasil', NULL, '["Jaime Larry Benchimol"]', 'Editora FIOCRUZ eBooks', 'SciELO Books', 'books', 1999, '1999-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Consistente contribuição à história social da ciência e da medicina no Brasil, que articula recentes avanços da história, filosofia e antropologia da ciência. Analisa, sem anacronismos, a trajetória que Domingos Freire descreveu no efervescente mundo das ciências biomédicas de finais do século XIX, desnudando a complexa rede que começava então a unir os médicos cientistas. Enfim, uma obra com o mérito de mostrar que, na ''corrida'' por compreender a febre amarela e finalmente anular os seus efeitos, o passo dos que ''perderam'' também bateu o chão sobre o qual se ergueria o pódio para os ''vencedores''.', '["yellow fever","Louis Pasteur","history of medicine","social history of science","microbiology","mosquitoes","scientific networks"]', '10.7476/9788575413166', NULL, 'https://books.scielo.org/id/6p4jp', 'https://books.scielo.org/id/6p4jp/pdf/benchimol-9788575413166.pdf', NULL, 'https://books.scielo.org/id/6p4jp/cover/cover_thumbnail.jpeg', NULL, 129, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-pz254', 'pz254', 'Experiência de doença e narrativa', NULL, '["Rabelo, Míriam Cristina","Alves, Paulo César B.","Souza, Iara Maria A."]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 1999, '1999', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'O conceito de ''experiência'' é o fio condutor desta coletânea dividida em duas partes: a primeira aborda a construção social da doença, em especial a ''doença mental'', enfocando as experiências de aflição através dos processos sociais e diálogos que lhe dão forma; a segunda focaliza o doente e a experiência do adoecer e do se tratar. A instigante análise aborda questões relativas à subjetividade, corporalidade e ação, aspectos fundamentais para o entendimento dos modos socialmente compartilhados através dos quais os moradores do Nordeste de Amaralina (bairro de classe trabalhadora de Salvador) identificam, explicam e reagem à doença mental.', '[]', '10.7476/9788575412664', '858567668X', 'https://books.scielo.org/id/pz254', 'https://books.scielo.org/id/pz254/pdf/rabelo-9788575412664.pdf', 'https://books.scielo.org/id/pz254/epub/rabelo-9788575412664.epub', 'https://books.scielo.org/id/pz254/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-t4s9t', 't4s9t', 'Questões da saúde reprodutiva', NULL, '["Giffin, Karen","Costa, Sarah Hawker"]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 1999, '1999', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Coletânea cujo tema central é a saúde reprodutiva, abordada com enfoques diferentes do tradicional. Contendo um panorama atualizado do conhecimento adquirido até o momento sobre a saúde reprodutiva da mulher brasileira, responde a uma demanda crescente por informações de qualidade. Fornece subsídios para tratar, de maneira integrada, saúde, sexualidade e direitos reprodutivos. Assim, torna-se instrumento para a organização e a sistematização da reflexão analítica relativa a resultados de investigação e a balanço de experiências de implementação de políticas sociais. Somatório de olhares de autores de áreas diversas que certamente estimulará o diálogo interdisciplinar.', '[]', '10.7476/9788575412916', '8585676612', 'https://books.scielo.org/id/t4s9t', 'https://books.scielo.org/id/t4s9t/pdf/giffin-9788575412916.pdf', 'https://books.scielo.org/id/t4s9t/epub/giffin-9788575412916.epub', 'https://books.scielo.org/id/t4s9t/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-5btwk', '5btwk', 'Teoria epidemiológica hoje: fundamentos, interfaces e tendências', NULL, '["Almeida Filho, Naomar de","Barreto, Maurício Lima","Veras, Renato Peixoto","Barata, Rita Barradas"]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 1998, '1998', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Parte do princípio de que finalmente uma malaise epistemológica se instala na epidemiologia, determinada pela incômoda posição de principal responsável pelas contradições da saúde pública neste fim de milênio. Assim, convoca estudiosos e profissionais a questionar fundamentos, explorar interfaces e formular discursos competentes indicadores de tendências.', '[]', '10.7476/9788575412794', '8585676507', 'https://books.scielo.org/id/5btwk', 'https://books.scielo.org/id/5btwk/pdf/almeida-9788575412794.pdf', 'https://books.scielo.org/id/5btwk/epub/almeida-9788575412794.epub', 'https://books.scielo.org/id/5btwk/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-889m2', '889m2', 'Epidemiologia, serviços e tecnologias em saúde', NULL, '["Barreto, Maurício Lima","Almeida Filho, Naomar de","Veras, Renato Peixoto","Barata, Rita Barradas"]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 1998, '1998', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Reúne pensamentos e experiências de diversas origens sobre questões de relevância na epidemiologia, com especial enfoque às relacionadas aos serviços de saúde. Congrega temas como diagnóstico e informação em saúde, avaliação de serviços e controle de doenças, na busca pelo uso racional de tecnologias.', '[]', '10.7476/9788575412626', '8585676493', 'https://books.scielo.org/id/889m2', 'https://books.scielo.org/id/889m2/pdf/barreto-9788575412626.pdf', 'https://books.scielo.org/id/889m2/epub/barreto-9788575412626.epub', 'https://books.scielo.org/id/889m2/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-nf9bn', 'nf9bn', 'Clínica e terapêutica da doença de Chagas: uma abordagem prática para o clínico geral', NULL, '["Dias, João Carlos Pinto","Coura, José Rodrigues"]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 1997, '1997', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Um verdadeiro tratado clínico e terapêutico sobre Chagas, que reúne os maiores especialistas na enfermidade. Os autores pretendem a difusão dos conhecimentos e práticas que habilitam o manejo adequado desta parasitose contidos neste ''manual'', principalmente entre aqueles que vivem e trabalham nas áreas endêmicas de ocorrência, na busca de minimizar os sofrimentos que a tripanossomíase tem imposto a populações. Com esse objetivo, a obra vem mostrar que não só a doença pode e deve ser prevenida, bem como é possível diagnosticá-la entre os já infectados e dar a estes uma atenção específica capaz de atenuá-la ou mesmo de curá-la em certas circunstâncias.', '[]', '10.7476/9788575412435', '8585676310', 'https://books.scielo.org/id/nf9bn', 'https://books.scielo.org/id/nf9bn/pdf/dias-9788575412435.pdf', 'https://books.scielo.org/id/nf9bn/epub/dias-9788575412435.epub', 'https://books.scielo.org/id/nf9bn/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-q5cc4', 'q5cc4', 'Os diários de Langsdorff - Vol. 1', NULL, '["Silva, Danuzio Gil Bernardino da","Komissarov, Bóris N.","Becher, Hans","Levy, Paulo Masuti","Braga, Marcos P."]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 1997, '1997', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'O zoólogo, botânico e médico alemão Langsdorff foi o mentor dessa grandiosa aventura naturalista:  entre 1821 e 1829, conduziu um grupo de pesquisadores e desenhistas por uma viagem de 17 mil quilômetros, estudando a fauna, a flora e o modo de vida do interior do Brasil.  Os registros, em textos e ilustrações, dessas cenas até então inéditas da natureza brasileira estão contidos nesses três primeiros volumes.  Um quarto e último volume - contendo mapas e reproduções fac-similares de documentos originais - está em fase de preparo.', '[]', '10.7476/9788575412442', '8586515027', 'https://books.scielo.org/id/q5cc4', 'https://books.scielo.org/id/q5cc4/pdf/silva-9788575412442.pdf', 'https://books.scielo.org/id/q5cc4/epub/silva-9788575412442.epub', 'https://books.scielo.org/id/q5cc4/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-hwhyp', 'hwhyp', 'Os diários de Langsdorff - Vol. 2', NULL, '["Silva, Danuzio Gil Bernardino da","Komissarov, Bóris N.","Becher, Hans","Levy, Paulo Masuti","Silva, Danuzio Gil B. da","Braga, Marcos P."]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 1997, '1997', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'O zoólogo, botânico e médico alemão Langsdorff foi o mentor dessa grandiosa aventura naturalista:  entre 1821 e 1829, conduziu um grupo de pesquisadores e desenhistas por uma viagem de 17 mil quilômetros, estudando a fauna, a flora e o modo de vida do interior do Brasil.  Os registros, em textos e ilustrações, dessas cenas até então inéditas da natureza brasileira estão contidos nesses três primeiros volumes.  Um quarto e último volume - contendo mapas e reproduções fac-similares de documentos originais - está em fase de preparo.', '[]', '10.7476/9788575412459', '8586515035', 'https://books.scielo.org/id/hwhyp', 'https://books.scielo.org/id/hwhyp/pdf/silva-9788575412459.pdf', 'https://books.scielo.org/id/hwhyp/epub/silva-9788575412459.epub', 'https://books.scielo.org/id/hwhyp/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-pt88n', 'pt88n', 'Os diários de Langsdorff - Vol. 3', NULL, '["Silva, Danuzio Gil Bernardino da","Komissarov, Bóris N.","Becher, Hans","Levy, Paulo Masuti","Silva, Danuzio Gil B. da","Braga, Marcos P."]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 1997, '1997', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'O zoólogo, botânico e médico alemão Langsdorff foi o mentor dessa grandiosa aventura naturalista:  entre 1821 e 1829, conduziu um grupo de pesquisadores e desenhistas por uma viagem de 17 mil quilômetros, estudando a fauna, a flora e o modo de vida do interior do Brasil.  Os registros, em textos e ilustrações, dessas cenas até então inéditas da natureza brasileira estão contidos nesses três primeiros volumes.  Um quarto e último volume - contendo mapas e reproduções fac-similares de documentos originais - está em fase de preparo.', '[]', '10.7476/9788575412466', '8586515043', 'https://books.scielo.org/id/pt88n', 'https://books.scielo.org/id/pt88n/pdf/silva-9788575412466.pdf', 'https://books.scielo.org/id/pt88n/epub/silva-9788575412466.epub', 'https://books.scielo.org/id/pt88n/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-3y5xk', '3y5xk', 'Equidade e saúde: contribuições da epidemiologia', NULL, '["Barata, Rita Barradas","Barreto, Maurício Lima","Almeida Filho, Naomar de","Veras, Renato Peixoto"]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 1997, '1997', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Trata da eqüidade/iniqüidade e de seu duplo, a igualdade/desigualdade, tendo sempre como referencial a saúde das populações, em textos que enfocam: a dimensão política das sociedades ocidentais na atualidade, fatores econômicos ou de organização social e, ainda, aspectos como idade, gênero e etnia.', '[]', '10.7476/9788575412640', '8585676345', 'https://books.scielo.org/id/3y5xk', 'https://books.scielo.org/id/3y5xk/pdf/barata-9788575412640.pdf', 'https://books.scielo.org/id/3y5xk/epub/barata-9788575412640.epub', 'https://books.scielo.org/id/3y5xk/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-bm9qp', 'bm9qp', 'Os médicos no Brasil: um retrato da realidade', NULL, '["Machado, Maria Helena"]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 1997, '1997', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Quem são os médicos, hoje, em nosso país? De onde vêm, o que pensam, como trabalham e em que condições? Recebem devidamente? A recente pesquisa "Perfil dos Médicos no Brasil", sediada na Escola Nacional de Saúde Pública Sergio Arouca (Ensp/Fiocruz), buscou responder a todas estas indagações. Este livro analisa os dados oriundos daquela pesquisa. Para melhor tratá-los, os autores apoiaram-se na teoria sociológica e em sólida base empírica, diagnosticando de maneira clara e consistente a situação atual desses profissionais. Torna-se, assim, referência básica e obrigatória para planejadores, gestores e pesquisadores da saúde, especialmente os que necessitam compreender aspectos sociodemográficos, formação profissional, mercado de trabalho, ética e organização social e política da corporação médica.', '[]', '10.7476/9788575412695', '8585471050', 'https://books.scielo.org/id/bm9qp', 'https://books.scielo.org/id/bm9qp/pdf/machado-9788575412695.pdf', 'https://books.scielo.org/id/bm9qp/epub/machado-9788575412695.epub', 'https://books.scielo.org/id/bm9qp/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-djnty', 'djnty', 'Raça, ciência e sociedade', NULL, '["Marcos Chor Maio","Ricardo Ventura Santos"]', 'Editora FIOCRUZ eBooks', 'SciELO Books', 'books', 1996, '1996-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Bela coletânea que reúne trabalhos de enfoques plurais e com os seguintes objetivos: abordar os temas da raça e das relações raciais a partir de uma perspectiva diacrônica, desde o século XIX até o presente, com o intuito de observar as mudanças e deslocamentos conceituais de forma abrangente; apresentar um conjunto de trabalhos elaborados a partir de reflexões em diversos campos do conhecimento (antropologia, sociologia, história, ciência política e literatura), revelando assim a pluralidade de enfoques através dos quais a tríade raça, ciência e sociedade tem sido abordada; fornecer subsídios para a compreensão do cenário racial brasileiro contemporâneo.', '["race","race relations","race and science","race and society","history of race concepts","racial identity","anthropology of race"]', '10.7476/9788575415177', NULL, 'https://books.scielo.org/id/djnty', 'https://books.scielo.org/id/djnty/pdf/maio-9788575415177.pdf', NULL, 'https://books.scielo.org/id/djnty/cover/cover_thumbnail.jpeg', NULL, 115, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-q5srn', 'q5srn', 'Política de saúde: o público e o privado', NULL, '["Eibenschutz, Catalina"]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 1996, '1996', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Instigante coletânea de ensaios - ora em português, ora em espanhol - sobre a articulação público/privado nos sistemas de saúde da América Latina, elaborados por renomados especialistas do Brasil, Argentina, México, Venezuela e Chile. A orientação dos trabalhos é diversa: uns são fundamentalmente teóricos, outros têm um enfoque macrossocial, alguns técnicos, outros filosóficos; contudo, todos expressam a preocupação com questões tais como: falta de eqüidade, cidadania, participação popular, poder, trabalho médico, seguros privados. A problemática da maioria dos textos contempla o modelo neoliberal latino-americano e seu impacto sobre a realidade da atenção à saúde em vários países.', '[]', '10.7476/9788575412732', '8585676213', 'https://books.scielo.org/id/q5srn', 'https://books.scielo.org/id/q5srn/pdf/eibenschutz-9788575412732.pdf', 'https://books.scielo.org/id/q5srn/epub/eibenschutz-9788575412732.epub', 'https://books.scielo.org/id/q5srn/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-fm4ng', 'fm4ng', 'Filosofia da História', NULL, '["Hegel, Georg Wilhelm Friedrich"]', 'EDITORA UNB', 'SciELO Books', 'books', 1996, NULL, 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'Nestas lições sobre a filosofia da história universal, a trajetória da humanidade é retrilhada e interpretada por aquele que foi o líder indiscutível do pensamento filosófico da Alemanha de sua época e um dos filósofos de maior influência em todos os tempos. Publicada pela primeira vez em 1837, seis anos após a morte do autor, "Filosofia da história" é a obra que representa o estágio mais elevado e desenvolvido de seu pensamento, sendo um resumo e uma conclusão de toda a sua obra anterior. Aqui estão presentes os conceitos fundamentais de Hegel: a idéia, o espírito, a razão, a moralidade objetiva (ética, social) e a subjetiva (pessoal, individual). Os mais importantes fatos e indivíduos históricos são descritos e analisados. É uma viagem no tempo e no espaço, que vai da Ática às Américas, passando pela Ásia, pela África e pela Europa. Da Grécia antiga à Revolução Francesa, acompanhamos a evolução do espírito em busca de sua plena realização na liberdade de seus desígnios.', '[]', '10.7476/9786558461630', '9788523003623', 'https://books.scielo.org/id/fm4ng', NULL, NULL, 'https://books.scielo.org/id/fm4ng/cover/cover_thumbnail.jpeg', NULL, 0, 'opds', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W35043312', 'https://openalex.org/W35043312', 'Entrepreneurial Potential and Potential Entrepreneurs', NULL, '["Norris F. Krueger","Deborah V. Brazeal"]', 'REGEPE Entrepreneurship and Small Business Journal', 'Red SciELO', 'scielo-network', 1994, '1994-04-01', 'en', 'article', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Before there can be entrepreneurship there must be the potential for entrepreneurship, whether in a community seeking to develop or in a large organization seeking to innovate. Entrepreneurial potential, however, requires potential entrepreneurs. This paper discusses antecedents of such potential and proposes a model based on Shapero''s (1982) model of the entrepreneurial event. We then discuss this model in light of supporting evidence from two different perspectives, corporate venturing and enterprise development.', '["entrepreneurial potential","potential entrepreneurs","antecedents of entrepreneurship","entrepreneurial event model","corporate venturing","enterprise development","organizational innovation"]', '10.14211/regepe.v7i2.1071', NULL, 'https://doi.org/10.14211/regepe.v7i2.1071', 'https://www.regepe.org.br/regepe/article/download/1071/pdf', NULL, NULL, NULL, 2416, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-th', 'th', 'Principais mosquitos de importância sanitária no Brasil', NULL, '["Rotraut A. G. B. Cônsoli","Ricardo Lourenço‐de‐Oliveira"]', 'Editora FIOCRUZ eBooks', 'SciELO Books', 'books', 1994, '1994-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'SANITÁRIA NO BRASIL Principais Mosquitos de Importância Sanitária no Brasil possui informações concisas e atualizadas sobre os mosquitos vetores de doenças no Brasil.Aqui são fornecidos dados sobre a morfologia e a biologia das fases evolutivas de adulto, ovo, larva e pupa, sendo abordados aspectos referentes à sua nutrição, reprodução, comportamento e ecologia.Para a identificação de adultos e larvas são oferecidas chaves ilustradas abrangendo os Anofelinos e principais Culicíneos já encontrados no país.São apresentados textos específicos contendo informações sobre as principais espécies dos gêneros Anopheles, Aedes, Psorophora, Haemagogus e Culex, dentre outros.Com referência às medidas de controle, são abordados os métodos químicos, a questão da resistência aos inseticidas, bem como as perspectivas dos métodos', '["mosquitoes","disease vectors","Anopheles","Aedes","Psorophora","Haemagogus","Culex"]', '10.7476/9788575412909', NULL, 'https://books.scielo.org/id/th', 'https://books.scielo.org/id/th/pdf/consoli-9788575412909.pdf', NULL, 'https://books.scielo.org/id/th/cover/cover_thumbnail.jpeg', NULL, 863, 'openalex', NULL);
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-jm5wd', 'jm5wd', 'Estado sem cidadãos: seguridade social na América Latina', NULL, '["Fleury, Sonia"]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 1994, '1994', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'Trata do sistema de instituições jurídicas e políticas de proteção social, com o objetivo central de apresentar ao leitor o padrão latino-americano de Seguridade Social, analisando suas origens, forma e tendências de desenvolvimento. A autora não se furta à polêmica: aceita o desafio acadêmico de construir um ponto de vista teórico com força suficiente para enfrentar os inevitáveis - e, para o debate, instigantes - questionamentos. Enfim: leitura obrigatória para os que querem entender e interferir nos rumos da Seguridade da América Latina, quaisquer sejam suas formações profissionais e convicções políticas.', '[]', '10.7476/9788575412428', '858567606X', 'https://books.scielo.org/id/jm5wd', 'https://books.scielo.org/id/jm5wd/pdf/fleury-9788575412428.pdf', 'https://books.scielo.org/id/jm5wd/epub/fleury-9788575412428.epub', 'https://books.scielo.org/id/jm5wd/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('scielo-book-wqffx', 'wqffx', 'Saúde e Povos Indígenas', NULL, '["Santos, Ricardo V","Coimbra Jr., Carlos Ε. A."]', 'Editora FIOCRUZ', 'SciELO Books', 'books', 1994, '1994', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Traz contribuições que exploram aspectos biológicos, culturais e sociais da dinâmica de saúde e de doença de tais povos a partir de uma perspectiva bioantropológica. Com base em estudos de casos sobre sociedades indígenas experimentando acelerados processos de mudanças socioeconômico-culturais, os diversos autores proporcionam um panorama atualizado acerca da questão - saúde e doença na pré-história, sistema de crenças e práticas médicas, mudanças nos perfis de saúde -, ficando evidente a pluralidade teórico-metodológica que atualmente caracteriza as pesquisas.', '[]', '10.7476/9788575412770', '8585676051', 'https://books.scielo.org/id/wqffx', 'https://books.scielo.org/id/wqffx/pdf/santos-9788575412770.pdf', 'https://books.scielo.org/id/wqffx/epub/santos-9788575412770.epub', 'https://books.scielo.org/id/wqffx/cover/cover_thumbnail.jpeg', NULL, 0, 'oai-pmh', 'editora-fiocruz');
INSERT OR REPLACE INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec) VALUES ('oa-W2073840323', 'https://openalex.org/W2073840323', 'Reinventing government: how the entrepreneurial spirit is transforming the public sector', NULL, '["Tânia Margarete Mezzomo Keinert","Claudete de Castro Silva"]', 'Revista de Administração de Empresas', 'SciELO Brasil', 'scielo-br', 1993, '1993-12-01', 'en', 'article', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'livro de David Osborne e Ted Gaebler tem causado sensação nos Estados Unidos.Figura entre os mais lidos e comentados do momen• to.A proposição de "reinventar" o governo tem ga• nhado mais e mais adeptos.Fala-se até mesmo no verbo to osbornize (Business Week, 20.01.92) em referência à aplicação da proposição do autor principal da obra, David Osborne.Mesmo o presidente Bíll Clinton, ao anuncíar o plano conhecido oficialmente como uRevi~ são de Desempenho Nacional"-destinado a reduzir a imensa burocracia federal -usou a expressão "reinvençào do governo" (Jornal US,4 1oday, traduzido pela Folha de São Paulo em 19.07.93).David Osborne é jornalista, escritor (publicou o li• vro Laboratories of democracy, escreve regularmente para o The Washingotn Past, Governing e outros) e consultor de governos (tanto republicanos quanto democra• tas, ressalva o prefácio).Ted Gaebler foi numager da cidade de Visalia, Califórnia e Vandalia, Ohio e presidente do Gaebler Group, empresa de consultoria especializada em organizações públicas.O livro Reinventig Government propõe uma rediscussão das questões de governo a partir de tendências e teorias recentes no campo da administração, utilizando conceitos formulados por "gurus" como Peter Drocker, Tom Peters, Robert Waterman, E. S. Savas, Ted Kolderie, J. Q.Wilson, Alvin Toffler e W. Edwards Deming.A discussão principia com a constatação de que houve uma mudança na concepção da palavra burocracia que, no passado, tinha um sentido positivo por conotar racionalidade, eficiência e uma forma de estrutura organizacional.', '["reinventing government","public sector reform","bureaucracy","public sector management","National Performance Review","organizational change"]', '10.1590/s0034-75901993000600010', NULL, 'https://doi.org/10.1590/s0034-75901993000600010', 'https://www.scielo.br/j/rae/a/QtRRmbz54mpLDndyDJBVdcQ/?lang=pt&format=pdf', NULL, NULL, NULL, 3349, 'openalex', NULL);
